-- RadioData_Flx.lua
-- 修復 live radio / TV 節目在多人伺服器英文環境下顯示英文的問題。
--
-- 根因：PZ Java 在載入 RadioData.xml 時，會用 Translator.getText("RD_" .. lineId)
-- 直接把 RadioLine.text 固化成「載入端語言」；多人模式由 server 送出最終字串，
-- WaveSignal packet 不攜帶 RD guid，因此 client 端即使有 CH/CN RadioData.json 也無法
-- 重新查 key。這會讓英文環境的 dedicated/host server 對中文 client 送出英文字幕。
--
-- 本檔在 OnLoadRadioScripts 之後掃描 server/SP 的 RadioScriptManager，把已固化的英文
-- RadioLine.text 反查成 CH/CN 譯文；頻道名稱則交給 client UI 顯示層修正。
--
-- 注意：Kahlua 對 Java private field reflection 支援不完整，呼叫 getClass()/getSuperclass()
-- 會在 dedicated server log 中刷出錯誤。因此本檔只走公開 API，不再嘗試讀取
-- RadioBroadCast private preSegment/postSegment，也不直接改 RadioChannel private name。
-- 反查表由 scripts/sync_translations.py gen-radio-map 自動產生。

local TAG = "[CatLangFor42]"

RadioDataFlx = RadioDataFlx or {}
RadioDataFlx.PATCH_VERSION = 5
if RadioDataFlx._patchedVersion ~= RadioDataFlx.PATCH_VERSION then
    RadioDataFlx._patched = false
    RadioDataFlx._channelPatchTicks = 0
end
RadioDataFlx._patched = RadioDataFlx._patched or false
RadioDataFlx._channelPatchTicks = RadioDataFlx._channelPatchTicks or 0

-- 頻道名稱不是 RD_* 翻譯 key，而是 RadioData.xml 的 ChannelEntry.name 原文字串。
-- UI 透過 ZomboidRadio:getChannelName(freq) 直接顯示這個名稱，所以需要獨立覆寫。
RadioDataFlx.CHANNEL_NAMES = {
    [200] = { category = "Television", key = "IGUI_RadioChannel_TripleN", fallback = "Triple-N" },
    [201] = { category = "Television", key = "IGUI_RadioChannel_WBLNNews", fallback = "WBLN News" },
