    ["Brandenburg needs your help."] = "RD_b09d93ac-2efb-4ea8-a581-74cdc5f98e94",
    ["Breaking news from Kentucky."] = "RD_08443583-75a4-4dae-8172-17bd58fac7fb",
    ["Breaking news from the Knox Event."] = "RD_ef508dab-da3d-4c34-866e-b5df0d52c335",
    ["Breaking news on LBMW."] = "RD_258eaa89-ae44-46e3-90f5-f19a9370d04d",
    ["Breaking news this hour!"] = "RD_2334acba-c049-495d-8ed8-39b0962c45fa",
    ["Breaking news."] = "RD_2146a338-6733-46be-a2bd-5c50449e813d",
    ["Breaking news. We have images of some of the victims of the Knox Event."] = "RD_db8cef61-b3a3-43b0-8dce-98c83c401d99",
    ["Bringing you the facts you need to know, as the Knox Event widens."] = "RD_eebec746-f9cd-445b-9bd8-bf9486dccc68",
    ["Broil, fry, bake - your choice."] = "RD_08ad0333-2e95-4a1e-846e-fd5155b26712",
    ["Brought to you by Kitten Knives - Fine American Cookware."] = "RD_28f9b202-f015-43e5-a6bb-84e9822bcd25",
    ["Building?"] = "RD_382809ff-4c3d-499f-8610-e88a0e6d60a7",
    ["Buildings set aflame. Fighting in the street."] = "RD_15e7bc62-36f3-4bde-92d1-c016cf765a78",
    ["Bullets to the torso... limbs... they don't slow them."] = "RD_c57f7391-099f-4cf1-8231-4a7acdc426f3",
    ["Burn in the rage of a thousands suns!"] = "RD_4ae929a7-5165-45d4-bbc8-bb8697af6d74",
    ["But Ali, I forgot all about the report!"] = "RD_ea31edfc-4ba2-4fa8-8ddf-8c96562338ab",
    ["But Danielle's got a story to tell. You've got the mic Danielle."] = "RD_0203b2fc-1147-4509-8d7d-e0daba757e18",
    ["But Fothergay-Stroud. He... he..."] = "RD_dac3411b-26e0-4bf7-95e9-7fd1b062c66e",
    ["But Freddy is such a deep and vivid character, he's wonderful."] = "RD_675f4d91-adb5-49f6-8db8-9cd7a5a8ca10",
    ["But I also see God in those helping each other."] = "RD_239d361c-80c5-4176-a750-93350a4aa5d6",
    ["But I can't go without you. The borders are closing tonight."] = "RD_8670434c-5015-4d3a-81e8-b6b28c3a4dde",
    ["But I guess Kelly has what they'd call an exclusive."] = "RD_4482867d-2732-4e3c-be17-887a621a0ee3",
    ["But I haven't taken a scratch."] = "RD_d6352f2f-7473-4806-b1b4-f41cb6db83c8",
    ["But I love you so much, and I guess I'm sad..."] = "RD_c12072dd-4707-4563-baf4-c319a78f982a",
    ["But I spent so much of my time fighting to get Suzanne's voice heard."] = "RD_ce8926d6-9488-46d2-bda9-ec3ddef406de",
    ["But I want to stay here with you, Sam."] = "RD_e427e37a-d892-4e2c-9eae-bea7b70bd2ad",
    ["But I'm okay."] = "RD_26288cab-cb24-4df5-96f8-8eae099ccaee",
    ["But I'm so glad you survived your encounters with that thing with the electric claws."] = "RD_fa7f48e1-41af-4cb1-afd6-a195d90e00dc",
    ["But I've got it. I've got the sickness."] = "RD_7bb25b14-c9e5-4ad3-a1e3-144195bf9f49",
    ["But I've got kids north of the river."] = "RD_c00a9ee4-c101-4ba0-87f8-18f56691ab1a",
    ["But Marie, if you're a firefighter, who's going to cook dinner?"] = "RD_42e9f803-58e1-4172-a243-401c62b4949e",
    ["But Nanny Bunny says that we must share!"] = "RD_030d3dae-c15c-44e7-a813-75b2b9220dac",
    ["But all we have is the word of these... dudes with guns!"] = "RD_ca525ef8-2ddb-40e5-bbb9-1149075aa8b0",
    ["But are his answers enough for Kentucky?"] = "RD_62aeb4bc-751d-4c51-9eec-c499f6d1a516",
    ["But at least this Event was stopped in its tracks. It's contained."] = "RD_edc18dcd-92b5-402e-952d-9ad5a802cc5a",
    ["But at some point we must ask..."] = "RD_d4a2a020-5940-451a-8a8e-54ddd247ae22",
    ["But at this point the Knox Event is contained."] = "RD_cb0107c4-0288-4549-a7e5-cdac31ee6099",
    ["But before we get to survival - let's nail the basics."] = "RD_47678484-cd61-4e31-b818-fad7262e80cb",
    ["But everywhere I look I see dead and dying people."] = "RD_5124a08d-d16a-4116-b6eb-8d1f71dbdc2e",
    ["But first Jim Rich brings us the latest..."] = "RD_b715422f-4475-4e0d-8164-f0cdab3717d7",
    ["But first, Seattle linebacker Stanford Watt speaks about how..."] = "RD_1d400d27-8962-4d9e-b308-3f9462804e2b",
    ["But first: controversy over the Los Angeles Tar Pit's cheerleading squad."] = "RD_162647da-bc23-4037-9db8-2f6e876ad8e3",
    ["But ghosts who turn people's heads inside out?"] = "RD_7083ec42-78f1-4c11-98c4-d0af273e9e0b",
    ["But he works in the Star-E-Plex."] = "RD_28281e96-16b2-46ff-9156-acafc9c15da2",
    ["But hey! There's no door!"] = "RD_b11ab71f-fae1-4431-9bec-aca3a845e6de",
    ["But hey, apparently we still go from the playlist."] = "RD_7ee773b9-e454-4ec3-9d7a-6dd98d9f47fc",
    ["But his mind is on Diane - somewhere inside the Exclusion Zone."] = "RD_e63fc44d-efc5-49f5-a630-c578d2ac4c19",
    ["But if the Academy are watching! Go for it!"] = "RD_4248b8ff-ae68-4853-8ea8-7b50bef1062f",
    ["But if the folk behind me make their voices heard loud enough?"] = "RD_1bb8edbb-5f6c-4019-91a4-276201c50e63",
    ["But if they think those cars can get anywhere anyway it's insane."] = "RD_38efba6e-a7a5-4179-a46a-3e0a850274f5",
    ["But if we cut the wrong wire, the city'll blow up..."] = "RD_76235296-23fa-4234-b837-82141a1fef0a",
    ["But if you don't leave tonight - now - you'll regret it."] = "RD_63ae8142-02a6-47da-9f10-bf8116b047d8",
    ["But in the main dorm. In the hall..."] = "RD_3364d9ea-5afe-4f3b-b40f-fd1c39aa1e02",
    ["But instead by a surgeon's scalpel!"] = "RD_1b9566ba-a53f-4e10-8997-68a4407a316f",
    ["But it did seem kinda noble."] = "RD_c6533dd4-b57f-42ee-bc91-2696c668acef",
    ["But it didn't kill enough."] = "RD_a64f1781-880f-463e-ae4c-64d6aecd6ed8",
    ["But it keeps out the elements. That's enough."] = "RD_73781365-fe9e-492e-8a52-c05dc94595e0",
    ["But it turns out it's bottomless, far as I can tell."] = "RD_ec780c60-c693-4baf-9286-5394e5ab0a10",
    ["But it's a reality at the Grand Ohio, Kentucky's largest mall."] = "RD_eaf14b0e-4c33-4c6d-bc45-e3de41d750b6",
    ["But it's better than nothing."] = "RD_f99fd57d-dfe9-4289-97a1-7d867d8e7e95",
    ["But it's getting dark."] = "RD_1838e0b1-f471-4cce-88f8-c72573f89f73",
    ["But it's not good."] = "RD_f02eb3a3-d5d2-4b75-b642-272ddf577823",
    ["But it's not too late for you!"] = "RD_9d94b3cd-852c-4b6a-a5fa-bb4fdcfeb038",
    ["But it's too late."] = "RD_67c96ddd-0870-43cb-a885-3e42fa5646d5",
    ["But it's true."] = "RD_2de52fbb-e3a6-45cc-8668-c6a0907e9246",
    ["But let's look at something apart from the virus for once."] = "RD_bba3263a-97fb-45b9-a6b4-14240253c076",
    ["But listen to what we're being told."] = "RD_03ee6e23-5392-4e21-85f6-4ade1cfb1032",
    ["But local gamer Sam Nix has a different opinion."] = "RD_06b73873-4864-4410-89b7-bbdaed0138bc",
    ["But making that kinda noise..."] = "RD_2ca2c8d3-7649-434b-90e9-bd10af7eaf32",
    ["But maybe if we had some more information, then..."] = "RD_0ddd5434-44af-4533-af56-7f494898ecaf",
    ["But my own mother has a large part in my life and work."] = "RD_463dad62-9d51-4dc7-962c-93941515111b",
    ["But my youngest is coughing a lot..."] = "RD_626869f3-1633-4112-9a0d-e3a84046d877",
    ["But nervous enough to break into a store and take a VCR?"] = "RD_3334207b-5dba-4695-a88a-2226651b557c",
    ["But now he's laid low with the fever."] = "RD_f12112e3-8b88-4304-9e0d-671cccb86a3f",
    ["But once you're through somehow..."] = "RD_b2be1172-1a7c-416a-a1e5-ded99de6a223",
    ["But please remember to respect our troops."] = "RD_af5a7769-f4cc-4bd6-9d73-ecd59b455439",
    ["But refuse to speculate on the 'confusion' now found within the Exclusion Zone."] = "RD_f9614b29-0a3b-44f5-8d80-1ef08dd97115",
    ["But shouldn't America know what they're doing too?"] = "RD_63df3eab-0ecb-4045-a2f9-085ae67f67ed",
    ["But something did."] = "RD_4cf88166-81ee-443d-8fe2-c60d43b672cc",
    ["But something stays on."] = "RD_3687ea39-bdf9-4821-8fd9-033c315c15d5",
    ["But sometimes the silence is even more damning..."] = "RD_48af083f-b72d-4a25-a0fe-d9ecc6c0bde6",
    ["But sometimes you've just got to survive, right?"] = "RD_7291af6e-8dea-4011-ab2b-54b48ec9c9e8",
    ["But still a chance."] = "RD_8a98a2e9-1cff-4885-ab3f-8a5c508dd58b",
    ["But still the people here are asking 'why?'."] = "RD_6f39d0ad-322d-4a43-8fef-59a8d797f6ed",
    ["But the Knox Event IS contained."] = "RD_9bd9c186-972a-4e4c-9c9f-4770e3647eb8",
    ["But the mailman is short-sighted, and never wears his glasses!"] = "RD_0d57e100-f85d-4bf3-8288-cb2985ecf850",
    ["But the man is unconcerned, his gaze blank, oblivious to his wound and the scene."] = "RD_0e34faa5-4965-44e1-93f7-d227e4bb7473",
    ["But the neighbors are on vacation too!"] = "RD_d5f010f4-8601-4c6c-be07-8483e1cefb70",
