    ["But then: bait."] = "RD_13b70353-12dd-4185-9bee-21626b593d56",
    ["But there is no agenda."] = "RD_280d0753-f5b6-46c6-a845-fa66762b2fb3",
    ["But there is panic, there's..."] = "RD_ef588453-4ccb-4c63-b003-341fed8d19ee",
    ["But there is... another."] = "RD_fbe7163e-b9a7-469e-9c60-4629ef9d115b",
    ["But there's a huge snowstorm in Louisville and all the phones are down."] = "RD_90efad91-fd26-4cd7-99b7-b10f256e6f87",
    ["But there's labs in there."] = "RD_b378b5ff-5fe5-45f7-bf8e-0a2f079fb8ca",
    ["But there's still no official word on the true danger of the biological threat."] = "RD_3fb56972-8f69-4657-b2c2-f11c96615ee9",
    ["But these pictures? These pictures just show true horror."] = "RD_43fc6721-2e1b-4949-9e55-afb086b9d657",
    ["But they've got scientists to talk to now. Guys in chemical suits."] = "RD_4741957a-b74b-4c64-8f8e-249dd5ace820",
    ["But this is Kentucky, people are scared..."] = "RD_2a48e3df-d549-453f-becf-ee196873752b",
    ["But this is clearly in the nation's interest."] = "RD_3a32eb81-2a2d-4219-b9f8-81ef34d3e24a",
    ["But this is contained."] = "RD_6c16c77e-f803-4e25-b245-6e7b25fadd16",
    ["But this is swift, decisive action."] = "RD_5d4c327d-57ea-498b-a949-da4ff4f8c066",
    ["But those people are NOT going to get better."] = "RD_c439f9f2-d125-4ff9-8e3e-698fee6f02ff",
    ["But thousands of fans traveling all across the States..."] = "RD_6cf64c5f-30e6-4263-8df6-05574817b995",
    ["But up ahead there'll be more bodies. Not quite dead."] = "RD_516a6b11-7736-4ef2-a343-3703330876e5",
    ["But we do know they're doing the right thing."] = "RD_8b794c78-f66b-49fd-93df-9bb09edd830b",
    ["But we don't deal in absolutes."] = "RD_4e264273-371d-40bd-9c66-d893c5fbd13e",
    ["But we don't want to pretend we don't have problems."] = "RD_f8bb7a95-c2d2-4211-945a-aa3514674938",
    ["But we haven't forgotten where we came from."] = "RD_8b165e71-7aa0-418a-98bf-68be55c55c69",
    ["But we know you're listening."] = "RD_7aa514f8-b2b5-49ce-a239-3a4faf434400",
    ["But we're alive."] = "RD_6c8389ea-2d80-4cc1-9bf1-f2604affb456",
    ["But what do the stars make of the Knox Event?"] = "RD_af13219f-7649-43dc-9d9b-da8328548b6c",
    ["But what if they're too sick to eat?"] = "RD_b9b296fa-47dd-42f3-ab3b-5cd31a844daf",
    ["But what is it? Do believe the reports of violence?"] = "RD_abbbf0f6-91ce-417b-8824-ee21c7f62e1e",
    ["But what's the point?"] = "RD_6df90367-5dac-4976-a453-b686476553c0",
    ["But when I called up the company, the number'd been disconnected."] = "RD_4236693d-2428-41d1-9a21-e1b9237acd8f",
    ["But who cares when you can call today..."] = "RD_7c2eb83a-ab50-4791-82ac-70dec175ddcc",
    ["But within this exodus there is a plague."] = "RD_6415bff5-d361-4779-a5a4-81334351ef47",
    ["But you can't break into Fort Knox. There are 41,000 troops around it."] = "RD_66fa3b5b-58a6-4d7d-a8ba-de6eab4319c9",
    ["But you don't believe in their judgement?"] = "RD_d6ec5d2d-670b-491f-87b4-20e94e4751d5",
