    ["But, out of nowhere, a new planet just appeared on our scope!"] = "RD_62bfea5b-99d5-425a-808e-bca347253b9c",
    ["But, the British judicial system..."] = "RD_fb90d1ac-f8b1-40e0-bafa-9a601efd9148",
    ["But, this is what was foretold!"] = "RD_e19574c4-4278-4629-927c-a481d37a21bc",
    ["But, where shall I go?"] = "RD_de59dc6a-b6e6-4689-9bb5-6f631845ac5b",
    ["But... it's not verified."] = "RD_0e173bfd-5dec-4a4e-baf3-ee423adcbf20",
    ["But... not everyone got the sickness."] = "RD_10b1931e-4d60-4631-ab9f-f683d4001264",
    ["But... what if it's too great."] = "RD_61ac48c0-4bd8-4956-9abc-85a47e5e2483",
    ["By the way, Tammy's in the last carriage with a bomb around her neck."] = "RD_ec618b0f-44c1-4749-be30-f259f97e2b67",
    ["Bye bye big spider. Byyyeee!"] = "RD_db62fdd5-2b00-4d52-bd3f-fdf668bcf8e2",
    ["Bye guys."] = "RD_ff9d8ecf-070d-4bd6-ab3e-5feec39243f1",
    ["Bye sweetie. Back at seven for pot roast!"] = "RD_94480020-c1de-47c8-931a-914c95174563",
