    ["COME TO THE TACO DEL PANCHO!"] = "RD_8af01ccb-40bd-4863-b668-b16fb1eeb746",
    ["Cake!"] = "RD_cb326038-5384-469a-b8d3-e9163dcce967",
    ["Call 555-6782 to donate to the Brandenburg Local Relief Fund."] = "RD_6a1d6ec3-b327-42da-b629-a6dd093a7d43",
    ["Call 555-GNOMES for a catalog."] = "RD_1cd5740e-06ff-40c3-9a70-280883be1076",
