    ["Call today folks!"] = "RD_4bc00fbc-ec2a-45ac-bb34-841dc4efcc62",
    ["Call us now guys."] = "RD_89d116c4-bf41-4f60-8b4f-6065dba1d4a4",
    ["Call your local dealer and book a test drive..."] = "RD_4eb4eb1c-de01-44b5-8c5b-78b5f1746846",
    ["Camps of refugees and bystanders have been removed."] = "RD_e878c068-7085-48a6-922b-7ffd3baae276",
    ["Can I ask why?"] = "RD_b13f45fb-d969-46cc-947f-1d47b85984b3",
    ["Can I hear a yee-hah?"] = "RD_fbc35c77-7a87-4917-befe-3141bfec8a0a",
    ["Can I see your license and registration?"] = "RD_c294591c-e9a0-4a7d-a530-9415d7991160",
    ["Can it be real? The Pole of Justice returned to my hand?"] = "RD_2feb4d0d-5953-48f6-8178-bbca6db2e7b5",
    ["Can we come in your news van?"] = "RD_7ee17890-ca01-4d4e-be02-bb25c38bfa01",
    ["Can you afford to miss these prices?"] = "RD_69a70ba7-487e-4197-a4e5-f2456098486d",
