    ["How do you react to the Knox Event as a man of faith?"] = "RD_856c37aa-f6df-4e10-ad56-56f4b078f367",
    ["How does that sound to you on the ground at the Event boundary, Kirsty Cormick?"] = "RD_38e536b5-d420-401d-a882-adfd677f9e83",
