    ["How much?"] = "RD_e0130246-7efd-4158-96ad-b8f11c9d5319",
    ["How the fuck is this happening?"] = "RD_a4547e14-1f5e-4844-83d7-c9e709df7b3f",
    ["How you doing James?"] = "RD_b78a450a-8dea-4b62-99bc-c4fe304cfd5d",
    ["How you doing? Welcome back to the Cook show!"] = "RD_f17f9259-0ab3-4928-9390-09e068ffc18f",
    ["How you doing? You're on the Cook Show!"] = "RD_85b904e0-14e3-4daf-b354-33a7eb31df83",
    ["Howard, you okay to talk?"] = "RD_69a11986-3888-4230-be18-d05dcc8ca0d4",
    ["Howdy Neighbor!"] = "RD_51a63f37-9d4f-41d3-be4e-260a0b70212a",
    ["Howdy folks and welcome to Tennessee for the OSCC national qualifiers!"] = "RD_4d45869c-4b22-4039-9552-2b339366222b",
    ["However he underlined there was 'no evidence' of fatalities."] = "RD_f321ef68-0699-414f-91fb-3d33295c5652",
    ["However scenes on the road from the Event Zone suggest it inevitable."] = "RD_3b1e71f6-b13a-4bb4-91cd-dde7be006de2",
    ["However, I have faith in the fine people of the Center for Disease Control..."] = "RD_690daf87-627f-4e99-85f1-9ae02c0362ed",
    ["However, I repeat: the Knox Event IS contained."] = "RD_a8dc2de1-9e0a-49ac-bd59-100516d0bdfa",
    ["However, as the picture clears, and more information is made available..."] = "RD_303c01f4-a6ac-42b5-8ef6-d199e78dac28",
    ["However, there are individuals who are NOT immediately endangered."] = "RD_d86d3064-08e9-487e-9717-d630417b3b15",
    ["However."] = "RD_d74bb2b8-8f5d-4acf-b874-5d412bc33252",
    ["Howie Zitron attorney-at-law!"] = "RD_c8bfe634-c825-4ba9-a891-996960a865b2",
    ["Huge numbers of civilians are laid low by sickness."] = "RD_1e6cf2b9-4a61-440c-9346-247e745fe3cf",
    ["Huge numbers of people - men, women and children - are falling ill all over Louisville."] = "RD_a6037f6d-e172-4b53-9aab-e544617800f7",
    ["Hundreds of people - thought to be infected - entered the area."] = "RD_e59574f2-bb5a-464c-a01a-0c9be0dc0679",
    ["Hundreds of people with the Knox Event infection..."] = "RD_62b0d2ee-b26b-4b9d-84f3-475c8598bb44",
    ["Hundreds of them over the perimeter. Thousands maybe."] = "RD_06f0f7d2-f0c9-4b86-baab-3d9c60dd6db6",
    ["Hunk at work, maybe?"] = "RD_99923b85-f0f5-4f51-be33-6286b53492f2",
    ["Hurr de hurr hurr!"] = "RD_9bf82016-a51b-4187-b527-a91ad954d1ea",
    ["Huuuu-"] = "RD_354e3bae-6902-4d5b-afef-ff4e6d954f71",
    ["Huzzah!"] = "RD_653cc063-72cd-4968-bff7-6ace03113817",
    ["I AM DEFEATED, BUT WITH MY OWN POWER OF THE MODERATORS I CAN END THIS!"] = "RD_e303e0da-10fb-4908-b07a-a44ce786195a",
    ["I AM HERE TO KILL JANE WRIGHT! WHERE IS SHE? WHERE IS SHE?"] = "RD_0e41e122-4194-4960-a9b4-0ce2323ec550",
    ["I AM X-371, SENT BY YOUR SON FROM THE DISTANT FUTURE OF 2003."] = "RD_8781a0b2-9e39-434e-abef-7249c1019123",
    ["I CAN END IT ALL!"] = "RD_25d04fec-f88d-4bd8-b585-7c6c3dc4b040",
    ["I LIKE BEING NUDE."] = "RD_315c6c21-5759-4087-ae2b-387e2e05d0b3",
    ["I ONLY ASK THAT WHEN THE NIGHT SKY DARKENS, YOU REMEMBER ME."] = "RD_4f019495-c989-495d-8c31-ed833ef9c7e7",
    ["I SHALL TAKE MY LEAVE. YOUR REALM IS SAFE."] = "RD_549a6a13-2d65-47d6-822f-e5411d891542",
    ["I STAND HERE WITH THE FATE OF YOUR KIN IN MY HANDS."] = "RD_7132ab1c-0a5d-4072-acf9-c955d2a0d451",
    ["I WANT THAT CAMERA SHUT OFF! NOW!"] = "RD_87ee3fbe-86ee-4beb-af29-a05c5b042ccd",
    ["I admit the odds aren't too good..."] = "RD_dbf9981e-dc5e-4220-b0e6-ef978c9439a0",
    ["I agree, my good and worthy companion."] = "RD_56ad5c5e-d4b2-40e9-957c-eb802e14e264",
    ["I always carry a paperclip guys, and so should you."] = "RD_eff1b184-fc08-4c16-b51a-7a46a3b8a8a1",
    ["I am 'ere to tell you one thing."] = "RD_bcd6bf7c-fb93-44f1-a49f-16d3fdfb397f",
    ["I am Dr. Oids."] = "RD_d5dfe630-bb8c-48b2-a706-7e2ffa6aa834",
    ["I am Joan. It's 48 hours since this all began."] = "RD_70119030-1d09-4680-af1b-eced1d9dab6e",
    ["I am John. I can't say how, but we've been allowed access."] = "RD_bc12607c-4c10-4b12-8873-079503e43a7a",
    ["I am a leetle puppy dog!"] = "RD_e20c46c3-f2a9-4298-b495-2bfd25560188",
    ["I am forlorn. To me, he was much akin to a son."] = "RD_f47d77b2-1e9d-4f2c-aca1-85d3c608a745",
    ["I am here to tell you something mooo-tiful."] = "RD_d4728e21-11bf-4100-9e0d-bede68c4cf9c",
    ["I am human, and to doubt is human."] = "RD_6e36fbcc-ca97-41be-9412-e9a625cf2d66",
    ["I am in hourly contact with the President on this matter."] = "RD_7cbba644-1d80-4239-a70c-c91109460ab2",
    ["I am in what was once a place for radio broadcast."] = "RD_f93b5b46-afd9-412b-acce-4a1b9d6d3bef",
    ["I am making this statement at 11AM on July 9, 1993."] = "RD_5416c659-bc67-423c-9c3e-60f8967aa5ff",
    ["I am now willing to reconsider."] = "RD_c398b2e3-db11-46f4-b1b4-856247945b39",
    ["I am playing on my slide!"] = "RD_ee0ad01c-ae98-4264-8f8c-ddff7ded46c2",
    ["I am the leader of the vanguard of the proletariat..."] = "RD_aa54d676-16e2-44ef-afdb-e31473cf01c9",
    ["I am undoing some of the damage, bringing back what humanity has destroyed."] = "RD_6ceb9776-a0d1-4ab3-88ac-7c67abd31ce9",
    ["I am, and I'm here to put a few fears to rest."] = "RD_d80a691c-0340-43be-b2d0-980fcd6709f6",
    ["I am. There are horrific scenes here."] = "RD_2cd76e36-1e63-4ea1-8152-0e145704a924",
    ["I ask our journalistic community to report responsibly."] = "RD_5f03af59-8783-4c16-b939-5acc9e8dc577",
    ["I assure the American people that every dollar I have at my disposal..."] = "RD_88a87684-c393-471e-905a-03ed9fa463f8",
    ["I awoke to fresh frost atop my ice palace."] = "RD_d8097354-de4e-483d-96ad-d8c2b0d41267",
    ["I believe in our ability to deal with the Knox Event..."] = "RD_8e4a59ad-04c0-46bd-af98-a8a8129dd81c",
    ["I believe that those... changed."] = "RD_4477c23b-1be2-416c-a1ff-efc9c2bae105",
    ["I believe... the NATION believes... that you are withholding information."] = "RD_c0294f92-cd49-40e8-8760-9a73b973c6ad",
    ["I bet they do. Okay Richard, thanks for the report."] = "RD_b5cf4580-c984-4886-819f-3356850a387a",
    ["I built a colony of space robots!"] = "RD_edd9953e-7ea3-4098-85db-98749dde509a",
    ["I came here to kill you."] = "RD_fe4d7e0d-6acd-43d1-96fe-36a7315db4fb",
    ["I came here, to this room, to pray with you. For our souls."] = "RD_8b68412e-4e99-4677-abf0-18866807d814",
    ["I can confirm there has been an outbreak."] = "RD_41cb500f-d8ce-4383-aca6-bc606796aefa",
    ["I can confirm, though, that it's a fever. And initial symptoms can turn to panic and confusion."] = "RD_5f8597d1-8ddd-410b-bc4b-e1dac8d73401",
    ["I can do her Ghost Dragon Sweep counter-move with my eyes closed."] = "RD_b8bbb03a-1668-4117-8a4c-aa996e13ea20",
    ["I can do this. I can do this."] = "RD_356f11d9-8b3b-4067-8a70-867f410499b0",
    ["I can hear you Jackie. I can confirm two people are dead."] = "RD_7170250e-6570-4ed2-8b8c-603e1c8224d9",
    ["I can only assume the spread has slowed, which is why they are confident. But..."] = "RD_fe13d21e-9bf2-4f22-8514-ffbe8b9141ed",
    ["I can wait. I suppose."] = "RD_fa0593eb-eb20-4c72-89c7-ff6faac03c6e",
    ["I can't believe it Mark! We left our little Jack at home - again!"] = "RD_e2022d2d-a289-406b-a247-28b029d64107",
    ["I can't believe it. Woolly mammoths! Woolly rhinoceros! Are they..."] = "RD_c277bc04-6a11-4209-8a4e-35274d8e3984",
    ["I can't believe it... an inverted 720 mash!"] = "RD_c24659d2-2ebe-471b-b3d2-69c7eba1b7b0",
    ["I can't believe these things come in that size!"] = "RD_11850386-6ac1-451c-896f-c6bcf382c86e",
    ["I can't believe this is how our lives end."] = "RD_dc478723-9fa5-40ae-92ae-51fdbe3a12b0",
    ["I can't even say what I saw."] = "RD_9f16aa81-163a-41ed-80f3-feff0fb0c519",
    ["I can't get that streaker from yesterday out of my mind."] = "RD_cd5799d2-a216-4e9e-8018-8c8d37a696be",
    ["I can't go. My kids... and he'll come back maybe."] = "RD_2f04a057-ccb3-42eb-ab3d-4b5fcd821e64",
    ["I can't tell you where I am, but I think I'm gonna be left inside."] = "RD_c9756761-deca-47f4-ba2b-5ee61e9b53c0",
    ["I can."] = "RD_ae08072e-22c0-4f56-a012-8cb6ac2db59d",
    ["I can. Yes."] = "RD_fef0a2dd-d37e-46db-ad1f-6b566862b096",
    ["I care not! My rage remains undimmed!"] = "RD_e6425634-4e65-4461-b24a-c36047200f8d",
    ["I cast the fiend into the pit to SAVE all we know!"] = "RD_96e9b75d-5360-4606-935c-55b0066e88c9",
    ["I come from the dungeons of ArchDuke OldWorld with tragic news."] = "RD_2de834a9-fe42-4833-a957-20752b45fbb7",
    ["I couldn't."] = "RD_00ef8b01-3b20-4069-81b8-755a5e22c11f",
    ["I did Diane. I didn't get far."] = "RD_a0464b84-00b5-429e-8d28-5f638ef8e9ee",
    ["I did it for you, Jacinta."] = "RD_81dd4a72-b476-428a-9370-b48800854cc2",
    ["I did it! I did it! All thanks to you, Father Mullen."] = "RD_8073de7f-7f1b-4339-b24b-c68994917e12",
    ["I did... didn't I?"] = "RD_7a362fcb-33e0-4f4c-9961-9599dec11ded",
    ["I didn't even know what a platypus was 'fore I went to Australia! Then I fell in love with 'em..."] = "RD_9addde56-4480-4d8a-81d3-51ca87fc8ff7",
    ["I didn't know anyone I was with but..."] = "RD_9956169e-66d1-4303-819f-f165251b1e04",
    ["I didn't listen in class. Too busy on the Football field."] = "RD_753ff3ee-7c6a-4300-bf26-f0ef715e5c51",
    ["I do have faith, and as an American..."] = "RD_f3f85f0b-5faf-4a45-8f36-8f6bae34950d",
    ["I do. I really do."] = "RD_86eb04ba-fcba-4831-96f0-c773404a196e",
    ["I do. Okay, onto the next caller."] = "RD_a492775f-e607-406c-b34f-768230e12987",
    ["I don't approve of your methods, Salatch, but you get results."] = "RD_cacb4193-7b43-4cdf-951e-ca3c6cb07654",
    ["I don't care about that stuff. It's just my body."] = "RD_542f3770-0baf-4c03-a17b-8d241992fa49",
    ["I don't care about the virus. I just want to be with my children."] = "RD_2ab35bbf-9dac-490b-a6b4-df297b8fcc71",
    ["I don't care one jot about the British Judicial System!"] = "RD_0d20c846-955f-4b63-a0ee-3889f6818ed0",
    ["I don't envy you."] = "RD_0a0d2295-b6db-4019-9961-546ddfd5ff87",
    ["I don't even know if they feel."] = "RD_ddac9986-8f20-481a-a908-fe0b719c01e0",
    ["I don't find the acting in this piece lives up to the material."] = "RD_61aec399-35ec-4194-92f2-09c08b498fcf",
    ["I don't give a GODDAMN that I'm on air."] = "RD_7cfe36fb-ee04-43ee-a60b-6127df63f910",
    ["I don't have anything planned for today so I'll just say..."] = "RD_aefd0870-e5ef-4c2b-85c2-dca66f0af04c",
    ["I don't know Madison."] = "RD_f6eba0b8-9cce-4633-8630-07472aadd24f",
    ["I don't know about you, but a good Chicken soup?"] = "RD_18f2d508-0c09-41d7-9c2a-7660a3a311bd",
    ["I don't know about you, but when I golf with my buddies..."] = "RD_a6503de3-c61e-4e13-9b4d-58448ed39dbb",
    ["I don't know bro... you'll have to be a pretty cool skater to impress her..."] = "RD_f49a6afd-635f-4e30-8249-b2a571f25d8b",
    ["I don't know how long this dang thing will take."] = "RD_33e5dccc-1b53-4d81-a82a-e52bcb26f19c",
    ["I don't know if I should..."] = "RD_512be66c-814e-4da0-ad55-38cdf0d6e970",
    ["I don't know if this pack still has any charge but..."] = "RD_fcbec3d2-1dc9-4bf4-9edc-878b37617eb6",
    ["I don't know much, but I know it when times are bad."] = "RD_69389fc6-d150-4165-96c0-0323bad45c56",
    ["I don't know that, I've been told that."] = "RD_10c8fbff-20bc-4d89-870e-51fed2c5c6f9",
    ["I don't know what happens next."] = "RD_3e46c5ef-aa39-4760-a270-76ead2c0c591",
    ["I don't know what it is but..."] = "RD_e837d36a-0906-49d8-903f-10af4fd8e503",
    ["I don't know what it is."] = "RD_9702f1ab-7c11-4a0c-9f2a-b22fd9683969",
    ["I don't know what's going on right now..."] = "RD_45a67502-b8d9-4fc1-9338-e3f5398abbea",
    ["I don't know what's happening on the other side of the water..."] = "RD_586290e2-de2c-42b0-9727-02ce34bc5867",
    ["I don't know what's waiting for me on the other side."] = "RD_793273c9-69bf-4763-9ad5-270721266a06",
    ["I don't know where she is."] = "RD_273dab6d-a843-4813-96a7-8913dd097460",
    ["I don't know why."] = "RD_b2fae644-b723-4832-a612-be4edddf9a9b",
    ["I don't know."] = "RD_931c1bb9-dfea-4d07-8abe-d62d4373cd5d",
    ["I don't know. I don't care. We've nowhere to go."] = "RD_d1ed684d-d1b2-4193-8882-c59151c6cea4",
    ["I don't know... but I'll never forget her perfume..."] = "RD_be50c790-1260-415c-b1a3-b231f38e16ce",
    ["I don't need to see the news, it's outside my front room."] = "RD_1fd0ac44-c64d-43a9-8dd9-c01c6012f6ba",
    ["I don't think it's a big deal. What about all those people we killed in Iraq?"] = "RD_1566b04d-ca12-4b89-84b9-c9aca7c7df7b",
    ["I don't think they're gonna go away."] = "RD_f0976683-c540-4025-9686-c9bf90f5fe58",
    ["I don't want a servant... <sobs>"] = "RD_3feecdb6-8d97-4840-a3c4-23155b0760ac",
    ["I don't want to have to clean up another wreck John. I can't keep doing it."] = "RD_ee3e33a1-ce10-4715-b436-1959f2fbd688",
    ["I don't want to hear it, Larry. You said all you had to say last night."] = "RD_65966c37-a39e-4bb8-b88d-d174844761a1",
    ["I don't..."] = "RD_81a76c9b-f1de-4b8a-bed1-15d0f2167218",
    ["I dress up like Abraham Lincoln for the whole day. Every year."] = "RD_b47364e1-b93c-4201-90d9-1168f617c14c",
    ["I enjoyed the byplay between Dr. Carter and Mr. Clancy too."] = "RD_59495963-beea-41ce-af22-4c4bae6b9b00",
    ["I even tried this little back road. All blocked."] = "RD_6368aab6-5aaa-4755-ae69-6228aad0274e",
    ["I feel for the people trapped within the Event boundary."] = "RD_e6f8bd91-462b-4d56-ace0-7fcbba6df47b",
    ["I feel like I've seen Hell."] = "RD_cec08541-f82d-4ff7-8cc5-36303fea7672",
    ["I feel like my brain is doing somersaults."] = "RD_c4889a73-1820-49d1-b23b-78a0d68e327c",
    ["I feel sorry for all involved."] = "RD_de4366eb-6fd8-424e-9ba6-a532528eeceb",
    ["I feel the rage of a thousand suns!"] = "RD_642a053d-1528-4fd1-a2a4-cb85b35344d0",
    ["I felt this disturbance amidst the spray of the dawn snow."] = "RD_a0d8361e-df3c-4930-b672-9679f7197b8c",
    ["I felt transported back to childhood, when..."] = "RD_ad58bbf2-af78-4d7c-b220-9f1a67933da0",
    ["I find it hard to believe that a just God, my God, could allow..."] = "RD_8f71aae6-22a8-4461-a2e4-20709e8f0491",
    ["I find it testing."] = "RD_d7c69f59-aa8e-4b5b-bed7-9c9c6237d8f0",
    ["I find some of the content in games so disturbing, even adults shouldn't have access to it."] = "RD_42ddd3fd-eb8a-4761-98cb-f23c2c298037",
    ["I first fell in love with movies because they were..."] = "RD_4a9da841-3a9a-481c-abb6-d4100988de29",
    ["I flew to the Austin headquarters of Ego Software to play an early build..."] = "RD_7f90abc4-45f4-4dce-b1a5-195865755751",
    ["I followed a strange signal and found it floating near a black hole."] = "RD_ee7fb0a6-2b50-4a4d-8f08-43ad33246f11",
    ["I followed her to Paris... Rome... Istanbul..."] = "RD_1d6ef837-8366-4d77-bc9e-654ac56e0836",
    ["I forgot to count."] = "RD_f2c0a9c8-6dbf-4ce5-8a3d-8a95923e816e",
    ["I found a gun in one of the offices."] = "RD_42cd54c1-e9ae-498d-bb02-5119599c6e44",
    ["I got a business in there, in West Point!"] = "RD_76e5c032-1e1b-4de4-9eff-7e79e646f051",
    ["I got a hole-in-one!"] = "RD_026e9399-5921-4ce9-aa71-9ee71b213215",
    ["I got a home! A family!"] = "RD_c9cd6cc6-7f14-4947-9c9f-d4ce24445099",
    ["I got a shock people!"] = "RD_99f46cc4-9931-4216-a556-876151731454",
    ["I got jumpy."] = "RD_5860e0a6-552e-4934-ae5f-3a67b088e2d3",
    ["I got something, Mr. H. A friend in the third precinct."] = "RD_1f193388-6812-4724-8206-e6d9b28bc25b",
    ["I got the fucking diamonds, Mr. P. But Mr. H got shot. Mr. E's bringing him here."] = "RD_ce804d78-6a7c-4848-842e-6288226b002e",
    ["I got told they've got scientists in there talking to them."] = "RD_0daf6a05-9ded-43fa-856a-ee10053bb10b",
    ["I gotta say, it doesn't sound very American to me."] = "RD_44de16aa-f00f-40db-9eda-c8574dc2feb9",
    ["I guess they got it."] = "RD_57c7f1ab-ec67-4027-b3cf-b55d15101265",
    ["I guess. Anyway I saw them down the road."] = "RD_f9f387f4-51ce-4dde-a597-56023c2becfe",
    ["I had NO idea that Scandinavia was such an AMAZING place!"] = "RD_55cb9d4b-c878-42b7-a601-e54d9f7b4d9b",
    ["I hate this... Fish pie."] = "RD_4eadd70c-ee77-413f-aadc-95e85d3842ed",
    ["I hate to say it, but many have been left behind."] = "RD_6af9a428-1709-41f4-9722-5b9b84a0f8c8",
    ["I have been bitten. I am not long for this world."] = "RD_8e2823e6-807a-42d7-accc-8bbc5be43095",
    ["I have faith in our Servicemen and Women to fulfill their duties..."] = "RD_43cfd043-73ff-48d1-b713-fbba9a5ea483",
    ["I have no objections! I just don't want you to say I have no objections."] = "RD_8b449469-92b8-4b99-84c2-484d7877fb64",
    ["I have requested that this broadcast play on all media channels embedded with my troops."] = "RD_cc2aef39-61c5-4279-80f6-f50bcefebe8c",
    ["I have the Knox Event infection."] = "RD_1923268d-9903-4068-a922-5a2fbac8fca4",
    ["I have to help make the breakfast now, Miss Irwin."] = "RD_c5f949cd-4248-4e5d-884d-188a8f7156a1",
    ["I have two pieces of evidence!"] = "RD_c61668cd-a031-46eb-b7d1-df4532df5b92",
    ["I have verified reports of more violence inside the Exclusion Zone."] = "RD_a41146d8-041b-4d47-98a8-a377e4c70781",
    ["I headed out on the freeway when the soldiers showed."] = "RD_b48aeb45-f50b-44d6-b5c9-10badebee31c",
    ["I heard are people trying to escape from inside."] = "RD_8ac4539a-71f5-4742-af53-8e9a971ab97b",
    ["I heard rumors y'all wouldn't believe."] = "RD_3923dbc0-738c-442c-8917-6c8ba8812363",
    ["I heard they were on the bridges?"] = "RD_bc476b0a-ef36-4a35-a6c0-253988953360",
    ["I heard this thing comes with one WHOLE megabyte of RAM!"] = "RD_4651c092-dc9e-41ec-b853-2f0cab516916",
    ["I hope not. I see activity, and I see action."] = "RD_540cc7bd-3628-4f5b-b586-fb8953317fe8",
    ["I hope their insurance is up to date."] = "RD_a36c9c83-9bc4-41d0-ae47-cfe0d91038d6",
    ["I hope they're sleeping well now."] = "RD_d912b134-a177-4a7b-9eb4-535d89897b42",
    ["I hope you fellers like it."] = "RD_894bacc5-61f7-4646-8527-1c0fccd6c1f0",
    ["I hope you're okay, Dad."] = "RD_fdb45f73-4ad6-412d-8cc9-44115a44f1d4",
    ["I hunt. I shoot. I fish."] = "RD_b49fd1c6-05de-4796-ab14-729a79766718",
    ["I just did."] = "RD_abc6b584-4660-46bb-ad35-b56686c79ac5",
    ["I just didn't want to know."] = "RD_891f8e97-0cd8-4b98-a83b-ec10f93de0ec",
    ["I just got a little closer to the truth Mantell."] = "RD_97fdec46-0bc6-4d0a-b8b2-2e3b6540506b",
    ["I just hope I can put that all behind me now. Live a small town, quiet life."] = "RD_fd5a726b-7389-41b6-9323-a5d27101eb31",
    ["I just love it when things go to plan..."] = "RD_03d7bc5d-3ba3-460a-a589-7a4fef592de9",
    ["I just need... Oh no!"] = "RD_16bfb662-4e63-4dba-841a-d95fac160c89",
    ["I just needed to call someone."] = "RD_ddf09c20-d209-444a-aa37-a32f79384a5f",
    ["I just recorded an interview with Pauline Simpson who has come from inside the zone."] = "RD_a4c67c26-b528-4d89-adc1-2366440aecad",
    ["I just saw twenty people in an Old Folk's Home die in an hour."] = "RD_8ed3362b-a52d-4b4f-a163-127d95d64657",
    ["I just tried to get out of my apartment."] = "RD_612a77f8-3101-47b5-a60a-034ed2bb20a3",
    ["I just wanna say this was planned."] = "RD_c8f9715b-cfae-41c9-abfa-19ce99a2dbd6",
    ["I just wanted to say thank you."] = "RD_4a69fb1e-a62d-440f-93e5-eb64c93fe0d1",
    ["I just wanted to say that the climbing gear you're selling today..."] = "RD_b255dfb0-3342-4799-9dbf-9a61dce32bc5",
    ["I just... did."] = "RD_82f30555-7adb-4bba-a366-cf937e0b25ae",
    ["I keep telling you. It's called R-469. It's a cyberkiller from the future."] = "RD_9577b131-184d-47e7-bba5-928550026f6c",
    ["I knew I had a problem when I started winning games..."] = "RD_3b697392-01fd-4792-a8e7-44b5d4e4e356",
    ["I knew you had an objection!"] = "RD_77fec826-06a3-463b-8bf9-e45466ac108b",
    ["I know him. I know the guy."] = "RD_c1f597a9-a8c8-470e-b1b5-9ccdb843babd",
    ["I know it isn't possible."] = "RD_310ebd0d-95d7-43cf-b50a-b54271aaca75",
    ["I know just how you feel, son."] = "RD_7f169797-7419-4216-8b27-d839f9bfbc7b",
    ["I know my photos and everyone else's only show the lights..."] = "RD_1a9060d4-8d64-4a06-abf2-0a6a7fbcbd3c",
    ["I know right? Those guys wear glasses and are all like 'horrdihooorrr'!"] = "RD_96b4e6fb-e957-42fa-9980-3541cf459091",
    ["I know right?!"] = "RD_06c1a644-a039-4e70-85f0-26bb3bc3bb00",
    ["I know that, and I know that I'm as good as dead."] = "RD_7604ac44-10aa-4f4a-9326-ea6325f8ed42",
    ["I know the Rourkes and Kavanaghs have controlled this town for too long."] = "RD_ea424f6f-ae25-4a2a-a87d-fd65f5167358",
    ["I know there's more Immune out there."] = "RD_20496ee2-76cb-424c-8c02-16f91281152f",
    ["I know there's something wrong."] = "RD_197baa71-f27c-48b2-987e-92e8ef40f589",
    ["I know this because four soldiers came to see me."] = "RD_80d8acba-16f5-429e-8e8e-5c8f52ae0a9b",
    ["I know what it is. I saw my wife with the same thing."] = "RD_cf031fa3-5beb-4d44-b35d-b7d7bbd3d135",
    ["I know what this thing is now."] = "RD_54d4a44c-5ce0-4e82-a23e-45045d394788",
    ["I know what you want and what you need."] = "RD_95d103d1-2c48-4f25-80b1-02dc52323f22",
    ["I know you killed Marie, Peters."] = "RD_4e185216-1eca-4658-806c-2af321b4f844",
    ["I know you're listening."] = "RD_3149bba8-b690-4502-957b-2c940ee2a6d6",
    ["I know, Larry. We both have. Nothing ever changes."] = "RD_8933ee4a-c40b-4d98-9a7c-6a0bc3a697aa",
    ["I know, Timmy. But she was the love of my life. I'll never find anyone like her again..."] = "RD_77de3750-e974-45e4-8739-e4ce1d643ada",
    ["I know, but it's true."] = "RD_338efb15-7f1b-476f-b53a-a02f3428ca52",
    ["I know. I know because I heard you say the same thing to NNR this morning."] = "RD_d7f92be7-848e-4169-9fa8-220f843e00f9",
    ["I know... it's been great, huh?"] = "RD_4a9a638a-d4f1-4452-a04c-952dc8aa7bce",
    ["I like bubbles!"] = "RD_d6e06e55-d70a-4f22-896e-05cff94a8383",
    ["I like bursting bubbles!"] = "RD_69d07a51-e2f4-495a-8109-f703c549b0fb",
    ["I like mine crispy as all heck, but do it to your liking."] = "RD_1479d319-a621-44e6-abe0-ab561e0445fc",
    ["I live in West Point. Own a bar."] = "RD_d5904cbf-dab7-40d5-90c4-c38a92ce42ce",
    ["I live just North of the river. She's up in Louisville."] = "RD_66c476c8-17f1-4e79-8430-392870392530",
    ["I lost everything..."] = "RD_d7d81a5e-2707-48b1-acdc-32f348503fa1",
    ["I love Mary-Beth, Dirk. I love her."] = "RD_b1d06c1a-9e73-46b9-8ffc-83f18fb12b9c",
    ["I love it when you get in touch Dean."] = "RD_6b2af433-dc55-4bbd-a982-de04fbc5f185",
    ["I love it. Who doesn't love positive feedback?"] = "RD_c32b4dd4-9f02-4e93-b2e1-c7f69b49778d",
    ["I make mine with an egg to hold it all together!"] = "RD_7b661604-8164-4946-a886-f42371a86cf2",
    ["I mean the flu?"] = "RD_bb0023cb-c212-4093-8517-1302f14f14e6",
    ["I mean, I just broke up with Victoria..."] = "RD_9734c5a1-c7b7-4e72-80c1-0c200460d3a7",
    ["I mean, it's 1993. There's gotta be other ways to call out."] = "RD_078a05ad-11b1-42f4-8e9e-6773f46ea3c2",
    ["I need my <fzzt>"] = "RD_3b581bab-3d31-428a-a1a3-94425a91011e",
    ["I need my MVC!"] = "RD_0823b575-83f5-4bc7-a96a-dca1b467168e",
    ["I need to be quick."] = "RD_be4dfa74-fcbe-4cf5-bd69-f2a4c4d338e0",
    ["I need to keep you informed."] = "RD_2c1dce85-7bbe-4e9c-87fb-195835711f06",
    ["I need to take Jimmy to ball practice."] = "RD_ddb77846-e734-4334-8ba4-6cf5a1f0a63b",
    ["I need you to tell people that..."] = "RD_11de8fd7-9b14-484a-a5cf-4fb44e3a2422",
    ["I needed a new place to rest my head, and I needed it quick."] = "RD_21934aeb-45d9-4cd4-8ce2-32a81e09329f",
    ["I never asked for God. And I never asked for a name. So I will go by Poet."] = "RD_8db2e8e9-6aac-49ae-894c-69c668c5befe",
    ["I never heard of that. Are you pulling my leg?"] = "RD_b89ef7b8-974f-4706-8cea-7194d8e7e27a",
    ["I never joke about my gadgets, Agent Spiral."] = "RD_d1af3525-b3ab-4c16-958f-d84add1bd134",
    ["I never knew friends could have this much fun!"] = "RD_d69002fe-e44b-4f72-b9e8-ba52383b38ef",
    ["I never saw that twist coming!"] = "RD_da3955bb-556a-4190-a4dc-0ea3faca701b",
    ["I never seen so much camouflage in one place."] = "RD_9bf24103-41bf-4dfd-867d-163e158c4575",
    ["I never thought I'd get used to the sight of shambling corpses..."] = "RD_546e5752-c876-4106-9075-a3c0a9ba7f75",
    ["I now know this is not the case."] = "RD_daf74eb4-1ba2-4cca-afee-41817716cef2",
    ["I only know there's more to it than what we are told."] = "RD_0365c885-b0ed-4abf-9805-c657cee056b7",
    ["I owe it to those kids."] = "RD_1e5ed0b9-0743-4186-8ddd-705042f9cc32",
    ["I put it to you that on the night of the 5th of July..."] = "RD_5265b4ad-34ea-46af-900c-e73abcd74523",
    ["I ran. Swam the river... somehow."] = "RD_ecb27627-d86f-4f2c-86b1-01de78801d70",
    ["I realize that lessons were learned from the entire Raleigh episode."] = "RD_109f693d-3ebc-451d-97f0-4fd6d093f26e",
    ["I recall. Several of my colleagues contracted the infection."] = "RD_6b8504e1-0bec-4636-a5c0-2a22639d3b35",
    ["I reject God. But Hell is real. Every fool knows that."] = "RD_4bf75385-c8a6-4e73-a269-4667b957f9d3",
    ["I repeat: the Knox Event is not contained."] = "RD_42de3805-5311-4ec0-afed-ad9efc03d1b0",
    ["I rolled a six!"] = "RD_54c89282-9d4b-4266-92e3-d1790fbfef88",
    ["I said no questions Richard! When we have news you'll hear it."] = "RD_58338de1-50ed-4311-b94e-cc511e2a8d56",
    ["I saw everything. You see, I was watching... through my scope."] = "RD_df26c11e-a0de-416c-81bc-21e3fc47ebb1",
    ["I saw the craft, hovering above the university buildings in Louisville."] = "RD_a3c077a9-fe77-429a-9a8f-7926678cb6c0",
    ["I saw these guys in plastic suits."] = "RD_b301d0b1-fa87-4899-933a-230a40634cfb",
    ["I saw you that day in '63, Matt. When Kennedy was killed."] = "RD_c15eccf1-3f1e-43dd-9d3d-18c6946f1ad9",
    ["I see God in those helping us."] = "RD_1bef902c-59f2-44a8-a21a-fbf413c5766f",
    ["I see nature all around."] = "RD_fd96d057-a5ad-4524-b100-39b0e212e3c0",
    ["I see the fool that hurled ArchDuke OldWorld into the Chaos Abyss is among us?"] = "RD_c7604bc4-c689-4bd6-8fd2-8797fc1de922",
    ["I see. And are there other people there?"] = "RD_7999f48f-3929-455f-98a8-7dd1d41e7281",
    ["I see. What kind of stuff?"] = "RD_9dc9e805-7312-491a-8406-f72adf63a3e7",
    ["I see... Thank you for saving us, Captain. But the truth is..."] = "RD_1d2d3cfb-6b45-4051-afe0-573cac47ba00",
    ["I shall."] = "RD_e65bb414-d2d3-4f15-a740-4f7d271719c1",
    ["I shut you down! Is Mantell with you?"] = "RD_98e4470c-6d42-4bb1-bdb1-5bc64317af0c",
    ["I simply do not understand the hostility, Paula."] = "RD_c16b2035-191c-4aa6-a414-5371bd136bc7",
    ["I spoke to Cindy Craddock, star of The Forgotten Element."] = "RD_e4529530-4652-460f-bc71-ed0b5b9228bc",
    ["I spoke to Dr. Polina Tutberidze, professor of psychology at LSU."] = "RD_4322728f-21f7-4cf4-aa65-d17ca7fa749d",
    ["I started listening. Every day I asked you questions."] = "RD_a8d13c74-e742-48b5-8aa7-39c0693dffb2",
    ["I still remember how warm the grass on that knoll was..."] = "RD_9009ac3d-5cf9-41a2-ab25-64217f807b09",
    ["I tell you why so simple..."] = "RD_7f8cc3e2-8a99-4618-87d0-da2f326340ce",
    ["I think I know what you're suggesting, and my answers are threefold."] = "RD_53c1f7a8-57a9-47a1-b488-e2c3db684399",
    ["I think I know. Do you?"] = "RD_5ef396a1-f124-418e-8fd5-2fa638c49d28",
    ["I think I'm seeing those procedures in action, Diane."] = "RD_16886b89-b029-4909-8ca6-9049b38225b3",
    ["I think it is Mike."] = "RD_7374eed6-cf5f-4058-8da5-11a75133796e",
    ["I think it's coming to you."] = "RD_0ecf5330-1e91-4d95-96b1-2fe8072daafe",
    ["I think often of your story about the crying of the foxes."] = "RD_d85d652a-43b1-4523-865a-781f2bca7faa",
    ["I think so."] = "RD_5b425f07-dcb0-49ef-b353-70683c03037f",
    ["I think so. I hope so."] = "RD_343bc57b-e623-454b-b39f-7ddb423d9fbe",
    ["I think so. I think they all got it."] = "RD_aa0605cb-2c4b-4e79-9bcf-e0315187179c",
    ["I think the difference is that in a JRPG numbers fall out of the monsters."] = "RD_8316e81a-aa3e-434a-8884-7e717e8df379",
    ["I think they know what they're doing."] = "RD_235cbddc-aa89-422c-b660-1a98fa4db1c1",
    ["I think they're dying. It happens so quick."] = "RD_c043051f-5525-4072-8bdc-16b6dd67d00e",
    ["I think we can expect developments in that area."] = "RD_25a2dc92-a0f9-4151-83eb-af396d703870",
    ["I think we can help you with your problem..."] = "RD_77ef3f8e-a2be-4146-8718-4bda4b01576d",
    ["I think you're gonna have to let go of the 'bad' thing."] = "RD_4a358bb6-e6df-4172-8876-5ca55e7b1569",
    ["I thought I'd try to check out the camp over on the Event border."] = "RD_e27bbbb1-7795-4a9f-87a9-7637214dd5c6",
    ["I thought death was just an absence of life."] = "RD_2b59a7bd-7f4b-493a-b8f0-88c4ebacc564",
