    ["I thought they'd look like a dead body."] = "RD_3790ecb7-a930-489d-bb4e-dd9a7efb5240",
    ["I thought you'd forget me."] = "RD_3fbf35c0-678a-4051-99e4-3f7fc5926d67",
    ["I told the players I already had a boyfriend, but they didn't care..."] = "RD_5eaff868-4622-41f0-9f08-610eacd611cf",
    ["I told you! Now you look even sillier! Hurr de hurr hurr!"] = "RD_6ea8cc87-c8e6-4b17-bdc9-ee9c1eb76ac6",
    ["I took my dog out the car and I just ran."] = "RD_1ffcb0dd-15d3-49f5-9ab4-c4e51ed91420",
    ["I totalled my truck a couple of months back, coming off I-65."] = "RD_c852633e-ec91-4c92-9b93-3752cd9496de",
    ["I understand Eliza."] = "RD_604b3ef6-e16e-4eec-9e69-12e279ae6698",
    ["I understand that love."] = "RD_2ef6c4cd-d862-4988-bf18-0154b48f9899",
    ["I understand the difficulties facing us."] = "RD_efdc9a75-b080-43f9-83cf-ffb5a3f06542",
    ["I understand the frustration because I'm like you."] = "RD_893fd722-e802-4bdb-ba3a-118f37c0f33c",
    ["I understand the frustration. I can hear you: loud and clear."] = "RD_25071aff-ef5f-48ad-aa20-cdc845c6adae",
    ["I used to work for the British government."] = "RD_f5d9bfdb-ed95-4cd6-81b3-ddf7eac36a02",
    ["I walked away. I don't know what happened next."] = "RD_0d048abf-6b35-4f60-bb0d-7fd3ca0a126f",
    ["I want a new car!"] = "RD_d08eca43-85b5-4479-96b3-6171ec3118ae",
    ["I want a new house!"] = "RD_a5de346d-cab4-43d5-8dc6-86b4023e8b5e",
    ["I want a new husband!"] = "RD_b539376e-f6f2-4174-b0a5-41f42d8eef0e",
    ["I want to be as human as this guy Tongo."] = "RD_a3ffd79e-d7f5-4311-93f2-17ac40ad30cf",
    ["I want to count bricks too!"] = "RD_3ee84835-d196-4abb-b629-405d1a38c112",
    ["I want to know some things before you go..."] = "RD_59696d7f-3d68-4ad4-952e-129b0ba79bc8",
    ["I want to know when my fellow Americans..."] = "RD_0da8e0fd-b878-41d6-b7c8-33a5a885b5af",
    ["I want to make healthy cooking as easy as..."] = "RD_f107d679-25d3-43ed-92d7-6f61c54d1ca8",
