    ["I want you back. Right now."] = "RD_dde36fdc-7b73-4183-9b24-e3cf936a3511",
    ["I wanted to tell you!"] = "RD_f184b781-6bed-4d8d-926b-31e0d1fc4f4d",
    ["I was a scapegoat. The Raleigh outbreak was AGAIN..."] = "RD_0bdcfaa4-8379-479f-8c3d-2130966916dd",
    ["I was all: two planks, three nails, bang, bang."] = "RD_889b6171-8199-4cfe-b01e-65e82d78e429",
    ["I was christened without my consent."] = "RD_8b570909-9f1a-4ad5-ab47-1d191c68d69b",
