    ["I was in there. I got away."] = "RD_3c4368cb-53d5-4db0-b359-1ac011a5e873",
    ["I was like - how come these dorks can do something so cool?"] = "RD_4519255b-aac9-48e3-8321-c75210c67b32",
    ["I was never working for you, Estevez."] = "RD_7385d234-fc87-4038-bca5-1eeb31ca8c8f",
    ["I was ready to do a live interview with a lady called Patricia..."] = "RD_811f33bf-76bc-4650-a4b5-dbd46fe37326",
    ["I was staying at my fella's and... I was gonna go back but..."] = "RD_fe361861-f021-4e53-a3bd-62bfa7da41e9",
    ["I was. Get it all the time."] = "RD_e3303d6e-fb75-45a2-a9ab-58cba3908982",
    ["I was. My Mom's still in there."] = "RD_c9e0f0ce-1e45-4e54-b3a3-87bc4a23f7bc",
    ["I went away to visit a cousin, but the night before..."] = "RD_c322d687-14c8-43a6-bbdb-9decc7179cf5",
    ["I went back to see my wife."] = "RD_d13aa873-d378-4441-a012-d80f0e96cf04",
    ["I will be able to provide more answers..."] = "RD_a33a9161-878b-47fc-a084-549ee52bbc6a",
    ["I will come back to you with more information..."] = "RD_40f5478b-f7b9-46a1-bf33-2cc7bcc2e0fb",
