    ["I won't spell it out."] = "RD_5c979aa2-17a4-428e-99c2-67ab970e98ca",
    ["I wonder who IS on it. Maybe... the President."] = "RD_5b1d81f9-f7c3-4203-b925-3de1ba52ab2f",
