    ["I'd like to apologize for last night's guest."] = "RD_00d1a98e-9595-4122-b6c2-232af60a5f52",
    ["I'd love to be on it. Just get away from it all..."] = "RD_220a6b20-c337-49ac-850a-ed883db6aec3",
    ["I'd rather be a living nobody than a made man in concrete shoes, Ponzini."] = "RD_9107eb66-3461-4052-a2c8-9958a53cfc34",
    ["I'll be at Central Park here in Ashland tomorrow at noon."] = "RD_6a759afe-be12-4b13-91b4-7b9d706333a0",
