    ["I'll check in when I have more to report Diane."] = "RD_c7d09e1d-59af-44fb-b753-9697629eafcc",
    ["I'll find that out further up the road."] = "RD_ab02ce8c-85d7-40db-8344-90221623a8d8",
    ["I'll get the flashlights."] = "RD_2d78166a-f4cc-49d3-9691-8ea45ad11cff",
