    ["I'll make sure to disinfect the line."] = "RD_80b8af0b-3140-4409-abba-043dc40f8dff",
    ["I'll never touch a stimulant again."] = "RD_c32d7fdd-e7d9-44ad-bd96-96e3f884f1bd",
