    ["I'll spare you the details, as y'all would blush."] = "RD_ced05294-7426-4a29-ad90-48572f61bbb2",
    ["I'll tell you what. I'll make a promise. If we're both still single this day next year..."] = "RD_d6623f6f-eb80-4f46-926c-c76d438a7e2a",
