    ["Iain, if you don't mind me asking..."] = "RD_42049117-b73b-43ca-b282-4b6da25eb81a",
    ["Icon Jeff Madingly, star of Rock Paper Scissors, has spoken out!"] = "RD_9777cd7f-6177-4ffe-8efc-81c17df9c787",
