    ["The roads have checkpoints."] = "RD_b7ccfbe3-3bb8-4ee7-a163-1fbfadf9dd07",
    ["The role was challenging though? Tough?"] = "RD_3cc7a314-54ef-40ea-bb1b-b23ba95354ef",
    ["The scenes are the same on each side of the collapsed Event boundary."] = "RD_d705e671-9069-4d09-80d2-15df8141ef75",
    ["The scenes of horror in Kentucky are not alone."] = "RD_85c2f643-057f-455a-8c63-ef71d475f399",
    ["The second is foraging."] = "RD_dd875aa3-b6ff-4418-a377-35bdee71f20e",
    ["The sectioning of an unknown, localized, contagion."] = "RD_3a3ad0ae-7644-48c6-8487-12ac4afc2610",
    ["The see-saw lets you play... together!"] = "RD_f6f022f4-02c4-4087-b663-3e35d6a33dd9",
    ["The situation in Kentucky is unexpected and saddening."] = "RD_1009b319-c826-40b2-ae82-c0e64233555b",
    ["The situation remains volatile."] = "RD_64d12d7c-db83-448a-8c17-1b1884f6b63b",
    ["The situation would seem to be unfortunate in the extreme."] = "RD_93967b2a-df8d-4227-bc5d-b36024e157f6",
    ["The small towns of Muldraugh and West Point..."] = "RD_cac1fa3b-ad93-47e2-a52e-458c0df4d63d",
    ["The smell of home, y'know?"] = "RD_ba88efb8-6046-4b62-ba0b-a85346f7d459",
    ["The soldier said he was sorry, and he shot him!"] = "RD_b37cfbdb-2bc5-4b64-b537-d553987035fe",
    ["The spread of the Knox Event infection is now total."] = "RD_e5e4e0d6-a047-4ffc-a417-9b3f38b6842f",
