    ["The still unidentified Kentucky outbreak'."] = "RD_e3a3f71a-ba6f-4a1f-aa33-3a9e86f955b0",
    ["The symptoms are flu-like, then it's panic and confusion."] = "RD_fc41e89d-20f2-480f-ab56-2d4471a17e59",
    ["The thing is Don, knowing what I do about the CDC..."] = "RD_1a35f228-6522-4144-87e3-d2a9427f9783",
    ["The things I'm saying - not many folks are saying them out loud."] = "RD_95f4c4f9-017e-4cbf-b1de-1beac2a41572",
