    ["The time has come to bear arms against this threat."] = "RD_178809af-f188-4978-a884-2b8d6cf60a5a",
    ["The time of deliverance for the proletariat is at hand!"] = "RD_1d77e6cc-2f7e-476a-8cbf-accba7b8183f",
    ["The truth is... pure hell."] = "RD_7a4c57ca-4360-4921-8713-d58551316a8f",
    ["The use of violence between sufferers has been reported."] = "RD_181b4ade-f1a8-454c-9bda-577b56d53eb0",
    ["The view is incredible, isn't it Jay?"] = "RD_5bfd6325-ea42-4e7a-b15d-807d9a596ad8",
    ["The virus <cough> has..."] = "RD_deb377bc-99a2-473e-b6aa-661def694e0f",
    ["The voice - that of General John McGrew."] = "RD_2f50f5aa-bd39-4263-b964-46925fe28903",
    ["The voice of reason!"] = "RD_87c9f3cd-f491-445c-8010-a4207d778662",
    ["The way it's being handled..."] = "RD_6340b76d-b2ee-4640-a9ff-45b392269b11",
    ["The way this started was highly contagious."] = "RD_ec76df47-36e3-4312-a406-09a1455e12f8",
    ["The what? Why would you do a thing like that?"] = "RD_9067be15-3813-4288-863c-210fd22db435",
    ["The whole town can't be under the control of aliens, Lester!"] = "RD_107855fb-50da-4242-bc09-8ba2894b4ede",
    ["The wife says she aint seen nothin' like it."] = "RD_bb1d0b0a-bbbb-44ad-a562-7e59e8a25417",
    ["The world is watching us."] = "RD_6bccf4d5-fd16-43a0-8300-28710838a03c",
    ["The world's greatest heavy metal band is coming to Louisville."] = "RD_88d61901-3822-4bec-b7c5-4ffb9542dcdb",
    ["The young one, he is dead."] = "RD_99dbb516-74be-4a5f-88a5-37171b5c15b0",
    ["Their aim? To get north. Over the Ohio river."] = "RD_a598c06f-1b3a-47f8-9542-485078ecbfce",
    ["Their assurance: that the Knox Event is contained."] = "RD_af0edcfd-692f-4022-833e-1afedb9762fe",
