    ["Their concern?"] = "RD_9013df14-eac3-4e99-af7c-634cbd68b4ab",
    ["Their homes? Sure they have. That's not good."] = "RD_495982e0-0a0f-42df-b67d-b9d02c7bdeb0",
    ["Their primary deployment: south of Louisville."] = "RD_b1ca550d-6c90-4d1d-a146-6d93600a36ee",
    ["Their problem? The 'do nothing' agenda of the President."] = "RD_bf45e0e8-ba0b-4315-9b61-f2eb96d38e02",
    ["Their story is one of horror."] = "RD_efc6821d-078f-4282-bdcc-3889a70737d0",
    ["Then I drive through, get taken aside..."] = "RD_7574ce0b-17a4-48f7-8ace-0c47cb38a5fb",
    ["Then I meet you."] = "RD_5c013232-603a-4f38-a774-795eff8c4989",
    ["Then I will go by Artist."] = "RD_58c849d1-01ea-4ddf-874d-3bebac96026d",
    ["Then add in some fresh vegetables."] = "RD_16c25fd1-7728-4f1e-a2cf-041e01ae97ad",
    ["Then build a rod."] = "RD_afb4e491-aec5-4607-a6ef-ffb4f7977006",
    ["Then check out the woods next door."] = "RD_8c9a85c8-04c3-4a71-a6c3-3426f2083892",
    ["Then don't forget those dry ramen noodles and..."] = "RD_c13613c6-ced4-4d1b-b565-f5c385f99875",
