    ["Then into the oven, and leave to get delicious!"] = "RD_5e29b81b-d45c-4fec-9a60-0e857843d364",
    ["Then let God go with him. The boy is a marvel."] = "RD_0e0e4301-4adc-4157-b5f3-dbb030a5f437",
    ["Then me and my friend fed in spool after spool of fishling line."] = "RD_d207130a-055b-4fb4-8ab2-bb8164da3e95",
    ["Then overnight... the blockades appeared."] = "RD_cdba3a7e-6b15-411a-bf24-b0bca7162e39",
    ["Then she died."] = "RD_657d47ec-2880-4d2c-90e7-d69d9c9e3cb6",
    ["Then sow seeds, and then... water 'em."] = "RD_fb843536-c351-4c16-9636-cd7c7182d9fd",
    ["Then take your bread, and add in that bacon."] = "RD_43030225-2881-431f-a553-7ba7cf4d8173",
    ["Then tell us some science!"] = "RD_c21a9a51-7d11-4331-9600-18cacbf304e6",
    ["Then the rumors of civilian confusion and bizarre activity within the zone."] = "RD_2ab593bb-947b-4345-a576-3cf5e8effffa",
    ["Then the stoplight is green!"] = "RD_4b0805f7-c9a8-455b-945f-54f1d2bd0ce8",
