    ["Then they say I'm clear and kick me out."] = "RD_94e20d7e-a073-4d4a-8cc3-54d7ab0d9c7a",
    ["Then they went for my fuckin' throat."] = "RD_697636de-0b22-40f8-9454-c48b532bf96f",
    ["Then tomato and your lettuce."] = "RD_320d9059-11e3-4770-b42a-71d76ec10bd4",
    ["Then use rubbish bags, or 'garbage' bags, for the interior."] = "RD_c76be599-e22c-4992-9d7a-e7a895e10930",
    ["Then we add cheese, ham - and we're almost at Bam!"] = "RD_56536c44-e816-4d22-bbc7-8fe3a89475e0",
    ["Then we found a note on..."] = "RD_0ac209dd-5758-4d98-8f84-27110bdedf16",
    ["Then why are the military pulling back?"] = "RD_1a16d07c-c619-48af-9d0f-4732e9a12fee",
    ["Then you find a goddamn gun."] = "RD_c0c136b0-efed-4b22-9c8a-3322df2e9842",
    ["Then you need fuel. Anything that burns."] = "RD_645eb206-000b-499f-a452-b0000ab14c53",
    ["Then, five nails should do you right."] = "RD_4dba4aa0-770f-48c3-9eaa-88623d5bd144",
    ["Then, if you're like me, just a bit of salt for flavor."] = "RD_1be68998-2d9c-4a1f-8d3c-5ffc9a381ee9",
    ["Then, in football, a preview of the Scavengers versus the Stallions..."] = "RD_0b94ac1f-0040-4406-bb06-7d67995d2e8b",
    ["Then, two days ago, we woke up and the cells were open."] = "RD_19f83a1b-9ac3-48fc-8cf9-19f29fbc2f40",
    ["Then... open it back up."] = "RD_adfc6c7b-c99b-43d1-a7cb-fea257aabedf",
