    ["Then: look at the sky."] = "RD_45bb7159-0a63-4e24-930d-477a4601583f",
    ["There IS violence..."] = "RD_00bde738-b5e8-4dba-9d10-2702aa2e5550",
    ["There appears to be no end to the descent."] = "RD_3de91db0-f51d-4922-ac39-f477db705d1b",
    ["There are barriers everywhere. Lots of perimeter patrols..."] = "RD_4c665102-1923-44f5-8a3a-0a08f51ed50d",
    ["There are bodies everywhere."] = "RD_8bb236bb-5f10-477f-90d4-84bcc408d7a0",
    ["There are bodies."] = "RD_27f867a8-fe67-422c-b078-4bf81213ef81",
    ["There are helicopters overhead, scientists in hazmat suits..."] = "RD_680f0582-37ca-4031-9c89-db25834a1526",
    ["There are many rumors circulating. Many falsehoods."] = "RD_296adae8-8283-406d-b10c-bc85ebc05f20",
    ["There are multiple casualties and..."] = "RD_efff2ced-5006-4217-9c37-79a10c2be53a",
    ["There are people here who have had NO contact with the infected."] = "RD_291383a7-6903-450f-b6e4-7b3f7669096a",
    ["There are pictures coming in from... England and..."] = "RD_3d096a6d-ba59-469c-af84-b78a6fd6fc03",
    ["There are reported deaths at the hands of the military there."] = "RD_397075d1-05f9-4d20-989e-4a92ed8179f9",
