    ["There are so many here, and so quickly."] = "RD_338f601b-06ee-4735-905f-16eb8e471d65",
    ["There are suspected cases throughout surrounding states."] = "RD_c2a333dc-c734-4544-92c9-cf441be24e1c",
    ["There clearly is, maybe was, a very communicable illness in there."] = "RD_58039aad-5de0-46ff-8b38-3aedc6376098",
    ["There has been no official statement."] = "RD_d89c583e-6230-44f7-a217-4c79b1a5307f",
    ["There have been joyful reunions, tempered by shock and dismay."] = "RD_01430d84-22fd-48e9-b287-157579e68482",
    ["There is Hell below."] = "RD_abeb06cd-a960-417d-8533-3e669b2646d4",
    ["There is Hell here."] = "RD_7c928342-7302-4e3e-9ada-b5a339f5b857",
    ["There is NO evidence of fatalities within the Exclusion Zone."] = "RD_c809b2c2-03c3-401c-9ded-6f2b82b3d4d0",
    ["There is a Forgotten Element."] = "RD_056eb78b-f554-4e63-be9f-df999d3f3792",
    ["There is absolutely NO need for further panic."] = "RD_c4c4bfa7-efac-419a-a835-e38ab4223632",
    ["There is an illness in there, and it is contained."] = "RD_607ed5d9-b5f3-49f8-8687-3325b24a3b25",
    ["There is anger."] = "RD_87677e5b-65b9-4837-931a-89cb933df96e",
    ["There is art... in eye popping."] = "RD_3403f2a0-626f-4d48-9cc2-0f57826ae28a",
    ["There is however a line we're seeing crossed."] = "RD_71d81b0f-33d0-4fbd-8d0f-5056b843cc08",
    ["There is no excuse. No excuse whatsoever."] = "RD_6f6abcaf-0a37-4080-94b4-5d7784c62d02",
    ["There is no known cure."] = "RD_0aabc8ed-a7de-4459-a4dd-2517fc10e52a",
    ["There is no word from the President or the Military beyond existing..."] = "RD_8554065b-153d-480f-8b31-aa3731a85521",
    ["There is now a renewed anger all along the camps on the boundary."] = "RD_4aab9201-8e4b-404d-9438-64e72f02d2d2",
    ["There is only Hell."] = "RD_d12c11fa-605a-4bb6-98ac-2cec5a8560f2",
    ["There is still good in you!"] = "RD_e18ce0cd-61c5-4096-84e7-10f3bb5a85fd",
    ["There is, however, a panic."] = "RD_7bc40bde-2ca3-4bfb-8da1-5594c5e53fd0",
    ["There is. There is something wrong."] = "RD_449dbcf7-a963-4950-83a3-53dc4e9bd19c",
    ["There it is again!"] = "RD_c8aefa38-b1a1-40b0-a003-5eb3f9152e12",
    ["There was a Raccoon."] = "RD_6e703116-4991-46aa-8cab-7021859ebeb0",
    ["There was a bunch of us, running for the north road."] = "RD_a5d200d8-1281-4cfa-a9cb-486ef994a664",
    ["There was a disturbance. A soldier opened fire."] = "RD_3687a4b3-8a98-4a9e-a1c2-f261f64f9993",
    ["There was a guy talking about it on Triple-N."] = "RD_8916ad5f-3a6f-44a4-88a0-0f0cf459e9b4",
    ["There was a lot of us."] = "RD_c05066e4-1189-4faf-9391-31e84d68fcd4",
    ["There was a tag around his neck. His name's Goblin."] = "RD_23d9acfb-aea1-4bbd-9820-be0731d79393",
    ["There was an attack at a rest stop."] = "RD_2dc538e0-cc17-4e33-ae0d-4e9c1d49aa7c",
    ["There was gunfire and, we believe, explosions."] = "RD_7752c5e8-e53d-449c-a937-44943c168cfa",
    ["There was this one lady."] = "RD_47807a60-cdae-4a9b-b782-0977cc88fdbd",
    ["There were fatalities today when a demo in New York turned violent."] = "RD_db05234a-c838-4789-b6bb-501dd61e7922",
    ["There were gunshots, and then there was this...."] = "RD_d11ea604-8822-426e-b226-4f32d6693436",
    ["There were more journalists than specialists in the temporary hospitals."] = "RD_4b52dc37-cf29-4124-8169-894788428c3b",
    ["There were soldiers there. They didn't want to let us through..."] = "RD_ff0fc8df-467e-432a-bc1d-9f19178304e0",
    ["There were thousands of infected, and they left their mark."] = "RD_20a8ee60-553a-45ce-add3-dbe20fd5555f",
    ["There were thousands of them."] = "RD_e6782a22-d4d1-40b1-94c2-e985c9d3dd04",
    ["There weren't enough soldiers. Or guns."] = "RD_5e9d816a-417b-4813-b6d3-257d7708799b",
    ["There you go ladies!"] = "RD_93c8a004-5612-443c-ac66-be1be4a309fa",
    ["There's a crowd outside, and it's growing."] = "RD_0dbd22d5-9bcf-466a-8d52-60462e5fb638",
    ["There's a dummy in his bed. He's been fishtailing us since page one."] = "RD_3184aeba-2a54-4af0-b319-dbc56a96e8ff",
    ["There's a fire, right there."] = "RD_8b07ad31-1eba-4e57-81cb-295f6ab4f71b",
    ["There's a goddam Exclusion Zone filled with evidence!"] = "RD_b927ebd2-9c09-4c32-a088-0327fe65b139",
    ["There's a goddam' TANK in my street."] = "RD_822437be-c475-4572-b95d-e1d83020a8c5",
    ["There's a green guy, and he goes all ELECTRIC! And a babe who kicks REAL HIGH!"] = "RD_7d48ed62-dba2-494e-9e8d-f9d0b0aa3495",
    ["There's a hell of a lot of dead people outside but we're safe."] = "RD_90ea5ce7-9dc3-46c1-a238-5064ab3ec109",
    ["There's a lot of angry, scared people here."] = "RD_54578124-87b1-4b7b-a636-294fbaa61d8f",
    ["There's a lot of bad stuff leading up to a casualty, right?"] = "RD_fdb946ae-796b-4958-b0e9-8b2df833bbf1",
    ["There's a lot of confusion. It could distress."] = "RD_a8495533-7fee-4c14-8881-6322cf6d0e63",
    ["There's a team looking into that right now."] = "RD_e320a9c8-ac18-4c7b-b22d-7010da6f8917",
    ["There's always this special moment."] = "RD_332a41ff-1a9b-4fb1-ae30-30f8139762eb",
    ["There's an image in amongst it all."] = "RD_a0bb50f4-11e4-42ca-9be7-f195b9c2acee",
    ["There's blood everywhere."] = "RD_85643fae-dba9-483a-877f-8e7a65dd035d",
    ["There's bravery in silence, folks."] = "RD_7cf44fc3-2015-4e77-b098-7ab0dcdb35bd",
    ["There's clothes racks filled with nails, boxes filled with shotguns and lollipops..."] = "RD_4126aac4-c4c9-4394-bc20-e5d2fe336f54",
    ["There's fear in people's faces as they once again camp out..."] = "RD_2c6d225e-d792-47bd-886e-8a71a483c67f",
    ["There's fighting in the line for gas..."] = "RD_ce17bc6f-c2fe-4527-86a2-ac00745e4142",
    ["There's gunfire on the other side of the camp. Frank!"] = "RD_217f594a-0907-46f4-82a5-0e2134317a7a",
    ["There's hundreds of them!"] = "RD_30996797-9d0b-4c24-989c-0f95647c9a9f",
    ["There's jam on the brakes? Sounds delicious!"] = "RD_c1a99216-256b-46df-a7b0-74807ce1733b",
    ["There's just a handful of reports of strange behaviors."] = "RD_17177d56-19ef-44f6-8fa2-36be6bb0ec0d",
    ["There's just so many of them!"] = "RD_6ac32ac1-120d-4b30-83df-f1caed1c7889",
    ["There's no better way to start the day!"] = "RD_72a6f9f9-bd94-492a-bf8d-e0caacb73610",
    ["There's no checks."] = "RD_605dba57-91df-4fc9-b6f3-432aad90d13b",
    ["There's no choice..."] = "RD_d17ddd74-42d3-4941-9cff-c4d91ee862ec",
    ["There's no evidence for any of that Abigail."] = "RD_f653f0be-7926-448a-9300-6380988cda05",
    ["There's no flights until after Christmas, and he's thousands of miles away."] = "RD_7cd3f9ca-d27c-40c4-887d-37e1e1c31177",
    ["There's no flights, there's no way..."] = "RD_5d969f9f-e8d8-4162-a6c8-c222c7482efa",
    ["There's no other way to say it."] = "RD_cda15668-b9e3-4dce-a3a5-41a7ed446a9f",
    ["There's no point in waiting for trucks full of stuff to arrive from the interstate."] = "RD_33786c53-06de-4e1f-9ac8-4aa18e102786",
    ["There's no reason to spread fear or alarm."] = "RD_865772b3-4238-4c1d-894f-fa7200deaeb5",
    ["There's no spirit gone up to the sky."] = "RD_6d8c51bf-4b24-44ff-bb2f-e200103e4019",
    ["There's no virus, Don. It's all part of their lies."] = "RD_5efe6db1-5211-4770-ae73-390fd3d48438",
    ["There's no word of 'illness' and 'confusion' outside the Event Zone."] = "RD_d72114d7-28db-4fd7-a982-15eb32769be3",
    ["There's nothing in their eyes."] = "RD_56a8cef7-44e5-48a0-914e-33becf1ca92a",
    ["There's one thing you can do for them right now mind..."] = "RD_335f9116-b23e-4c3b-862d-88ebb14a667b",
    ["There's other things. I get hungry there... but if I eat a watermelon, I get drunk."] = "RD_65a9799a-a1dc-47c3-892d-dfa02a29b5e2",
    ["There's pictures of the flu, there's pictures of the infection."] = "RD_844bfd46-eb62-4c46-9686-47bc8c3a1a8f",
