    ["There's something wrong. My controls won't respond... Rogue!"] = "RD_061df0ad-6841-41f4-be28-ccad157f8b5f",
    ["There's the news folks."] = "RD_49283845-745d-4534-9f2a-51a23d63c55b",
    ["There's this guy. Bloody clothes."] = "RD_5e78a099-f226-4d94-8800-ccfa1b45e430",
    ["There's violence in the border camp."] = "RD_840ca614-19e9-430d-9993-80a722b5ff42",
    ["There's..."] = "RD_f4ffaa34-a386-4250-9b29-ca04affc74da",
    ["There, next to Ms Tupper-Waring."] = "RD_da160b1e-038e-4f02-a7c2-705cfab1f7e5",
    ["There, she was waiting for me."] = "RD_ebb0856f-31b9-48f6-b121-822d579ccf5d",
    ["These are dark days, but as a nation we can and will prevail."] = "RD_2d983bff-597a-4fd6-be30-e094b9882a5b",
    ["These are people's families you're talking about Mike."] = "RD_682b33cf-c320-49c3-93c3-c7e19983f908",
    ["These are the end-times!"] = "RD_09abd3ff-0653-42f9-9455-32af3b5eea53",
    ["These boys protectin' those people - we don't know their orders."] = "RD_0c924041-c64c-4cf2-a4fb-c2d7115dd15c",
    ["These days, Greene's is kind of a big deal."] = "RD_142e4ada-1fae-4abe-974f-885dc6aa8964",
    ["These fine leather jackets - 50% off!"] = "RD_6283a048-8191-4d04-8624-4d9492c7dc45",
    ["These guys... all standing in-between us."] = "RD_96d80efe-f798-4901-9ebc-25080578ded4",
    ["These images show today's running battle between masked youths..."] = "RD_ce98252a-4e30-4532-b46e-bdf328380815",
    ["These ones are poison, and these ones are safe to eat."] = "RD_83513d26-8dcf-44e0-985d-3b07f4d76119",
    ["These people have been released from a military camp inside the Zone."] = "RD_06b4cdc2-1202-4cbe-a26a-83eeeab9c09b",
    ["These pictures clearly show Knox Event infections..."] = "RD_a129dca0-bcba-436c-a7af-3a2b14de26d5",
    ["These pictures show an infected attack on the outskirts of Louisville."] = "RD_1774b4ba-416c-4bb6-b950-41c749fc9f1a",
    ["These pictures show military forces setting up shop in the heart of our cities."] = "RD_6c1fe212-f69a-4b63-b49a-25d8111fc3ae",
    ["These pictures show the moment an officer was struck by..."] = "RD_db0607eb-bd26-4ebf-a7c6-1168e58c89c5",
    ["These prions have been building up in countless generations of cattle."] = "RD_af0fc0c2-cb7b-43ed-bd51-290e11bf1a5d",
    ["These recently released survivors aside: the infection rate is total."] = "RD_ce37aa68-6b68-4254-abdd-e28cbf246259",
    ["These shelves will be empty."] = "RD_6e07cfea-9f3b-4dfa-83a5-bf914a886836",
    ["These test results are terrible, Lester."] = "RD_5ad4db83-6b3c-4af6-8ad6-f72ca5da3841",
    ["These things. They're empty."] = "RD_b0da458a-7e73-4c45-8c49-73bf445ae918",
    ["These work overalls? 80% off!"] = "RD_5735ca0a-e59f-498d-aca7-3cfc331f81df",
    ["These... twenty long years I have kept something precious safe."] = "RD_d6969673-2d2d-4b44-abda-90087320c1a4",
    ["They are related Tom. And you're gonna get our sub and the Queen back."] = "RD_938df7cd-b3f0-42e3-9fcc-aa81673122b8",
    ["They are scared, hungry and come with shocking revelations."] = "RD_91591fed-3123-4654-8029-297d8d14a290",
    ["They are shocking. If you have children in the room just..."] = "RD_193cf3b9-f332-41d3-9fb8-166995001587",
    ["They are, however, dazed and confused. Panicked and nauseous."] = "RD_429b568b-8d16-461e-ae51-cdeb3499e713",
    ["They attacked. It was dark."] = "RD_06e48cc5-9e77-4b70-8f71-64246c46f78c",
    ["They believe you are refusing to address the issue..."] = "RD_51eea6c4-bc68-4b00-95d5-642064824a35",
    ["They bite, they maul..."] = "RD_416219ec-b4ab-42a4-a8a3-386937f50e0b",
    ["They blew the damn thing up?"] = "RD_2e2e6463-e4df-453e-bec6-d6d641ae2da9",
    ["They bring shocking tales of violence..."] = "RD_8b9c117e-922f-42b1-a08b-eddfadfa6321",
    ["They called it quarantine."] = "RD_cc67c912-5dbc-40cd-b150-e1b48dd9b328",
    ["They came in... through the wire."] = "RD_b3730c8d-49bf-45b1-bd38-3fddac989ede",
    ["They came when it got dark - threw me and my boy in a truck!"] = "RD_8528ce4f-d3d8-44bc-ad21-88b9874a2c7d",
    ["They can see other people. From other times. And places."] = "RD_9ea43691-9ade-4db7-b1d5-b5d4abc3e067",
    ["They can't get home. They can't speak to their families."] = "RD_94bedac7-2f2e-4b0d-ba43-c8c2a6517194",
    ["They can't stop it."] = "RD_2008424c-41b9-4b1f-ba02-c139f01f830a",
    ["They could be dead in there!"] = "RD_465c503a-bcea-4edc-b2c2-fc6b2e7d56ab",
    ["They created that event boundary in DAYS to protect me, and to protect you."] = "RD_169e3e5c-daa2-4c5e-9db7-4e0c440e3e85",
    ["They demand RESPECT, not suspect... er..."] = "RD_26ba1771-ba5f-42cd-97c3-b70ad43cf8b0",
    ["They did it fast, and they did it effectively."] = "RD_92b5842c-10a8-416e-b100-fd742519041d",
    ["They did it in one of the most militarily senstive areas in America."] = "RD_ed794a35-aa43-4eb7-aebd-337ca84c1712",
    ["They didn't let me in. I got ID-ed."] = "RD_e36423a6-0fa6-4dd2-90c0-4a432f8d7cb8",
    ["They don't ask questions."] = "RD_5eba4ccb-10c1-44c3-98c4-8cbd26ab0e9e",
    ["They don't examine for any infection."] = "RD_e13caba7-2e82-4051-a69f-87622707044d",
    ["They don't have time to look back out."] = "RD_a3a057ab-5f2f-43f5-b47d-6411ff6e63b4",
    ["They don't think, they just... want to bite."] = "RD_2ce466cf-d938-42f6-9f8c-b94eae394ee8",
    ["They don't want panic."] = "RD_1ccf723e-05b8-449c-93ec-95a67ff88616",
    ["They don't want to risk more riots."] = "RD_e4b97f82-089f-448d-b0c2-bdd2315e0ac7",
    ["They got labs in there, they got secret facilities."] = "RD_c2b2e126-2038-4711-9ff1-7d0a7137f4d3",
    ["They got sick, they went crazy, they died."] = "RD_90ed9ed3-33e5-4fc3-a444-1598748676d1",
    ["They had a print-out. Said soldiers checked them for bites."] = "RD_a9d94e4a-0222-49d5-922d-a1d1b5caa477",
    ["They have been held in a local military base in..."] = "RD_9821e99c-8c2f-4a0f-92f0-aa77e929713d",
    ["They have been let through, we don't know why, by the Army."] = "RD_ccbf1621-104d-47f0-914f-c47dabaa16ab",
    ["They have science stuff in a military installation."] = "RD_0d398a7b-2212-4534-a733-ca2543976f2d",
    ["They have to plan for all contingencies."] = "RD_243e368b-d883-4bf9-97b1-0c11cdcd5020",
    ["They heard the fighting."] = "RD_d073cf54-4b04-4e7d-bc53-f20a928ce35b",
    ["They held this thing inside once."] = "RD_f2098302-6d22-44e8-a3fd-c2708984b5f1",
    ["They just appeared."] = "RD_a3659a28-7dc9-4d27-bbb1-f25076e20d20",
    ["They just shot her."] = "RD_45c45da5-ae43-4d30-8a43-718ad3696539",
    ["They just want to move on."] = "RD_867be425-08ef-4c51-ab43-47717edec083",
    ["They kept us in a military camp."] = "RD_01e1f6fd-a9be-4785-b4c8-a1b75519bbef",
    ["They knew a storm was brewing."] = "RD_e482da8f-08f5-4e44-82f2-f2deae982dab",
    ["They knew this might happen."] = "RD_85bcb4a1-4dd5-44bd-a02a-a1c3e59e4ffa",
    ["They let me keep my little dog Jiffy here!"] = "RD_3128b857-f0d6-4762-9a96-6a1fc227b311",
    ["They look after us here. It's like a second family."] = "RD_d394e147-f7df-48ff-b6a4-8a67ed9ac8b8",
    ["They look so... so dead."] = "RD_ce5eb750-6086-42ae-abc5-69f3f1037619",
    ["They look... separate, but the same."] = "RD_4bf15d8c-fc2e-4ee9-bb2c-d01c989072ff",
    ["They may be your family, they may be your friends."] = "RD_0e7bd1c5-e8b8-4ac4-81bb-7fa9cc2e831e",
    ["They move, but they're dead."] = "RD_23d7b8f8-9e05-46ae-a37d-0e2d3a7f8dee",
    ["They never came back."] = "RD_447c33ea-fa51-4d15-97e9-2bc54f1efbd4",
    ["They passed me by Clare."] = "RD_695a6f50-95f0-447d-acea-0a2297bb8347",
    ["They pinned it down."] = "RD_fd533134-cae1-45f6-9c47-e7b08688822a",
    ["They pulled her down. And..."] = "RD_e9c08ec7-7465-467f-a016-fd5cce1d2b0b",
    ["They put us in a school hall. Too many people, too few beds."] = "RD_51c8a0a3-9b2f-4916-a199-8fcdc7f90433",
    ["They rolled out from their bases, and they protected America."] = "RD_4f110315-7bfe-4a67-800d-e5365eb59b72",
    ["They said it was a quarantine."] = "RD_194e3aa3-4fea-40d0-ab91-64b07cb01c1e",
    ["They said it was a quarantine. Then one day we woke up"] = "RD_ea61b98c-047b-4a3e-8f59-22be2be1aff5",
    ["They said to bring 'em out food or they'd burn us down."] = "RD_138dc53a-d70f-46f7-b1a2-551a81c395bc",
    ["They say it starts with a fever, but I missed all that."] = "RD_1cba97ec-cc3e-49a1-b7a6-5e38cc8636b3",
    ["They say it's contained, but you can't stop death."] = "RD_fa4725fe-3f1b-4386-ab2a-c4de0c700816",
    ["They say they're protecting us."] = "RD_e63dcb6d-3ff7-4440-adfa-cd260546ffc9",
    ["They say we shouldn't be worried..."] = "RD_e5f66148-1765-43de-aaa3-5cf065f9ef3f",
    ["They say you really would. So... for the corners."] = "RD_8c7e4b2d-9a89-4552-aecd-e8587fca9757",
    ["They shine a light into my eyes. Take a blood sample..."] = "RD_746c1d08-d204-4fc1-89d4-e23a9d4ec162",
    ["They shot my dog!"] = "RD_a58ff8c1-f2ff-4eee-89d0-367624957bb2",
    ["They shout a warning, then you get a bullet."] = "RD_34bfd86e-e27b-4607-ac72-02ff12c02009",
    ["They shut the bar, but that didn't stop people breaking back in."] = "RD_adfc10fa-f135-40ea-b9e7-be3fd75a7299",
    ["They state that the need for panic is over..."] = "RD_a0f4c35e-c5ce-4160-ae46-56e60d2264df",
    ["They test on dogs?"] = "RD_3ef28b21-c41c-483f-ac87-043ad2abc053",
    ["They think it's no longer easily communicable."] = "RD_c2d58da5-0537-471c-b091-485b5da0b715",
    ["They took my Chris for tests, but he came back okay."] = "RD_1cc34156-3c65-4467-9c16-3818f37e29eb",
    ["They trapped them in the Event!"] = "RD_f7969cd4-fb78-41cd-b868-a408f78fc0e5",
    ["They try to kill you."] = "RD_673cdb12-cca8-4a5a-93e5-20d558eae740",
    ["They walked into camp during the night."] = "RD_f1be994f-97be-41be-b60e-bd2b19d57884",
    ["They want answers? Is this a result of the area's chemical testing in the sixties?"] = "RD_e2f3f0c6-6bf4-4e2e-8c10-12e73de1d41b",
    ["They want to stay - in tents, in local buildings. This is their home."] = "RD_5fa4b879-0315-4f17-bbb3-7d35aa3a509d",
    ["They want us away from there."] = "RD_77c1aebd-612a-4352-b91d-72f35ed13a6c",
    ["They watching the same news I am?"] = "RD_b73f01c5-d41c-4f87-ac84-e4c461c02c0d",
    ["They were held against their will..."] = "RD_0c54c286-3087-4390-8a36-951568961556",
    ["They were kept fully fueled so they should last a while."] = "RD_e8f990ee-9df1-4534-88b2-92b4ee66bdbf",
    ["They were laughing about it, but they weren't joking."] = "RD_2ff5a94f-8c05-4c07-a714-70890fcac8b7",
    ["They were ready for their duty. They got involved."] = "RD_791dc9db-f0e1-4d4a-aa15-30e3f7d6b866",
    ["They what?"] = "RD_82d8c0c9-1938-48fe-99e6-6c58a63e9c05",
    ["They're all here. And, guess what? They're angry."] = "RD_e8ac73dc-5abe-48f4-83f2-b80cab072aba",
    ["They're all lying to us, John!"] = "RD_c809e13d-1255-4465-9df6-cf125e83a09f",
    ["They're all on two feet, but they're in a bad way."] = "RD_b46389b2-c688-4a8d-aae3-21deff253cae",
    ["They're angry because they don't think they know the full story."] = "RD_e1187759-abab-4018-b107-f252312c4746",
    ["They're as scared as the rest of us."] = "RD_b389c666-8f0b-4bbc-9ed3-817228348c57",
    ["They're busy looking in on this... let's call it a 'Knox Event'"] = "RD_2b83ef40-a51e-4c58-95a4-99ace4603865",
    ["They're closing the bridges!"] = "RD_184f2fc8-3b31-4869-96e5-9606883fb49e",
    ["They're dead, Diane."] = "RD_e096acb2-272c-431a-8c8d-6dffd5e4aa6e",
    ["They're dead. They bite. You don't want to get close."] = "RD_72d58f1c-a427-453f-8825-dfceb6c81464",
    ["They're dead. They're actually dead."] = "RD_4bd6b05e-fa81-4e82-b854-5659433b01d0",
    ["They're doctors. How can they do that?"] = "RD_65f8d21c-e0f0-4f0c-9204-69e57969c55d",
    ["They're dying in there, we know that right?"] = "RD_a975df1c-b4ae-49bb-b10a-a1978f287562",
    ["They're eating Janine."] = "RD_95301c54-0991-4762-b465-428a5a7b0e28",
    ["They're everywhere! They came from every side!"] = "RD_4d30388c-9ca8-4b44-80b6-db42ff9f4068",
    ["They're everywhere."] = "RD_41509625-acb1-46ce-b22f-6b452c7c6d20",
    ["They're giving up Louisville?"] = "RD_b5c9354e-209d-481d-bb8c-e74eeeee37df",
    ["They're gone now, and so are the dead."] = "RD_db9858c7-1bd9-4694-acec-762595aaa334",
    ["They're gone. My daughter. Your families."] = "RD_d16be721-ad3d-4086-b7e6-5824331ea270",
    ["They're gonna come back. Everyone knows it."] = "RD_a5918367-1c9e-48c5-985d-963f8ccc17f7",
    ["They're hallucinating."] = "RD_64ad16c6-7d18-4726-8753-0ba6578564bf",
    ["They're just lying at the side of the road."] = "RD_0b3e3d3a-4dc0-48b6-9c68-e1cecd4e62aa",
    ["They're just practising for the local play. It's in French."] = "RD_62bceb6d-5935-4009-a9a7-e4eee0471242",
    ["They're just saying what they want them to say."] = "RD_6b60419b-51ad-46e8-b3db-29cb4487991b",
    ["They're lying. They're lying to us."] = "RD_1ac79d53-7c8e-47a3-9ba9-af5efb97eaa0",
    ["They're moaning. They're groaning."] = "RD_c6241fc0-e337-4705-be6c-ed3c45d42c37",
    ["They're not even human."] = "RD_fdcfcc6b-c7f2-4d10-8045-82fdbc4875cd",
    ["They're not picking up at Mom's"] = "RD_851a40d5-75dc-4f25-a541-cfbbde250ab2",
    ["They're not picking up at home."] = "RD_b0ed45c2-f5ce-465e-8ef4-81b85383a5aa",
    ["They're not tellin' us nothing!"] = "RD_fec33769-7318-4c22-a704-6b255e391521",
    ["They're on the floor."] = "RD_0c786181-6b1c-4e95-bb97-a6173afb4131",
    ["They're pushing back the exclusion boundary."] = "RD_61cb755b-b781-4bcd-b50a-33141f1008e2",
    ["They're regular men like your son, like my son."] = "RD_bb360a78-d8c4-44c7-8ad0-a5fe8ac5a4a7",
    ["They're relying on us to keep calm and have faith."] = "RD_9f5d0905-c082-4980-b5ec-c45bf427286a",
    ["They're running fevers. They're incapacitated."] = "RD_a56ffe24-b6c9-426b-b648-62321e734688",
    ["They're saying Somalia in Africa."] = "RD_631750a8-8e3a-47e7-b6bb-f0018075e2e1",
    ["They're saying it's contained, so I can only imagine..."] = "RD_c70ce321-c955-475c-9779-651756916be5",
    ["They're saying panic and confusion in there."] = "RD_7f1e1fa7-93af-4d02-901d-1ddd1584c5ef",
    ["They're saying... Norfolk, England."] = "RD_8db26c91-2aac-40a8-847c-a789af840f73",
    ["They're scared of catching a cold, so what?"] = "RD_d6d254e3-829e-4c74-844e-52a08195746e",
    ["They're shooting anyone that goes to leave."] = "RD_32abd42b-4d25-4775-bc38-3dbfd3e67414",
    ["They're smilin' when they go up them..."] = "RD_2b54a98e-1358-49e9-8033-3661b2e7d0f2",
    ["They're still there. In their chairs."] = "RD_aaa9eec1-d528-45c3-a981-46c4d3c4becc",
    ["They're stone cold. One of them..."] = "RD_6decb8d7-92a4-4833-af87-5c2e39457172",
    ["They're the US Army ma'am."] = "RD_f4c4e0d7-bdea-492c-9337-d5e7482be36a",
    ["They're trained for this kinda thing."] = "RD_9e624159-a16d-4a7a-84aa-e17fe6a64c57",
    ["They're vegan. I'd put every dollar in my wallet on that."] = "RD_bf2ac8b5-c91e-4644-920d-2916d48732ba",
    ["They've armored that Valuline. Our bullets bounce off of it!"] = "RD_2391c3bd-e2b9-4664-9066-37c2454118f6",
    ["They've asked us to say: 'Stay. Where. You. Are.'"] = "RD_c17fa922-3dcc-42ba-af7f-5444e2e780de",
    ["They've been coming for us for years."] = "RD_b61bd1ad-17df-4237-8c45-343da7812e26",
    ["They've been feeding cattle to cattle!"] = "RD_9e5d4ee2-9ba8-4cd8-9494-3be2612b3f14",
    ["They've got experts!"] = "RD_92573ae9-9bd4-49b6-8e68-879882d0c673",
    ["They've got it pinned, but for how long?"] = "RD_467622f8-1838-4cd2-b197-7ae1bdd97eba",
    ["They've got people doing tests right now!"] = "RD_9da5a8c6-12a5-44f4-b2da-2c918efe7d77",
    ["They've got snipers."] = "RD_687365f7-960d-4dbc-9282-d68e0efcb8ea",
    ["They've got the best in the business. Heck, the world..."] = "RD_29d16028-701b-4bfc-b5bd-a2eaeb0bee52",
    ["They've seen me."] = "RD_5338a826-a0da-4ed1-85df-f20a0143373b",
    ["They've taken all the food."] = "RD_6fe3413d-17f5-4bed-aede-087e6434a025",
    ["They... laid Camille to rest for me."] = "RD_21e9fddd-eaef-41ea-923d-6331d8f84463",
    ["They?"] = "RD_c54cf0bf-d739-46a3-acbe-64f2552555e4",
    ["Thin crowds here today, but the authorities have ruled..."] = "RD_8760fb51-3663-45a9-a9a8-e3d5cf7a27fe",
    ["Things are changing here."] = "RD_11e4939e-304f-456c-a5c4-a35f6bab56a3",
    ["Third, the Army is in the process of very effectively containing an outbreak of unknown origin."] = "RD_968d5575-2538-4a43-a406-002e6e3ca5a1",
    ["This Loveheart is becoming something of a bother. He beat up all our men."] = "RD_ec6b10b0-7690-442c-a12f-50bf62708c36",
    ["This afternoon: a press conference to allay fear and explain the Exclusion Zone."] = "RD_f72b7d99-ba67-4045-bc8a-a9f21feb0476",
    ["This all in response to the unprecedented move made by the WHO..."] = "RD_ca3fb02f-6abd-4b44-9618-4200d5fb59ee",
    ["This broadcast will be set to repeat."] = "RD_061f2e55-e448-410b-a61e-cb943a72d611",
    ["This came after a statement from General John McGrew..."] = "RD_967d1ec5-2517-4e1e-9df4-59b11092c41a",
    ["This can't be real."] = "RD_055aac50-3099-408b-b231-cfd26a0fa99c",
    ["This coat? It's from FashionaBelle."] = "RD_07a033a7-76ff-4aa6-acf9-17c4e442b5aa",
    ["This community was held, and tested upon."] = "RD_5472625e-24a5-40fb-93e2-1d38c285b698",
    ["This could be it... couldn't it?"] = "RD_d06e47fb-b996-490c-a90a-aca28aef8150",
    ["This county has been split in two, and folk are scared."] = "RD_89ecd099-a815-4352-bded-8d078cf920e1",
    ["This feels like an endgame, Joan."] = "RD_0566d003-7035-472b-905d-6e5aa081cfca",
    ["This has been Jackie Jaye."] = "RD_faa8f83a-402a-4d38-818c-3ff0e54feb0c",
    ["This has been an endorsed message by the Democrat party."] = "RD_845f8b39-5e62-4cb3-a735-8ebeb16ef64e",
    ["This has been an endorsed message by the Republican party."] = "RD_92d1d873-d94f-4e94-8c50-a55a7ea88d00",
    ["This has been widened to: Chicago, San Diego and Baltimore."] = "RD_38dc82e5-b200-4208-8dfe-9dd07ff822f8",
