    ["You can't just turn out the lights over that many counties."] = "RD_74702d9e-e206-4d1d-a847-00d5a5d58add",
    ["You can't keep a lid on this stuff."] = "RD_aa3bb915-7950-4f40-a1a3-b51a0406f5d9",
