    ["You're way out of line Hargrave."] = "RD_9f66988e-7ced-496e-af44-9b945b81f8ce",
    ["You're welcome, John. Anyway, we've had a few car wrecks recently..."] = "RD_fa049975-fcd2-4c2f-8e8b-099b622d5ef7",
    ["You're welcome, Paula."] = "RD_1625e05c-41d0-42ce-a907-6b345fb832b9",
    ["You're with KnoxTalk Catherine..."] = "RD_8c5908fc-033b-4f63-8461-34e3c828ff15",
    ["You're with Late Night Love on Knox Hits."] = "RD_fed60985-5d2d-4851-b2f5-3af6ff4a1fd6",
    ["You're with WBLN. Developments today from the White House..."] = "RD_9679782c-2429-41bf-a8a2-7da584427a5c",
    ["You're... dead wrong."] = "RD_a31286e6-394f-40df-9d43-47c8b6d39f96",
    ["You're... kidding?"] = "RD_6f7cccd7-111d-4b52-995f-65e7cedcaa63",
    ["You've already sacrificed so much for me - your money, your café, your pride..."] = "RD_90c613ef-2ece-4697-abfc-807a3290c37e",
    ["You've been a great contestant."] = "RD_37481d30-a23e-42b8-aceb-d746a88ec8a5",
    ["You've gone too wide Paul. Sorry. Last chance."] = "RD_8b077a9f-452f-4cb7-b37d-b76cbdb1eb88",
    ["You've got a camp."] = "RD_56d27802-e9ac-4fa1-861a-55d091dc08c3",
    ["You've got a water supply."] = "RD_0b5ac31b-32d9-4be3-9c69-29e900107f4d",
    ["You've seen the OSCC and Formula X..."] = "RD_31aa7996-3618-4fdc-a0ed-671128587173",
    ["You've stopped the developers and saved the town."] = "RD_8c5c69db-2e6d-4278-95df-7a8a7d763c13",
    ["Young one! Young one, no!"] = "RD_053fad79-2d5c-47fb-b614-ee42af682e15",
    ["Young one, what is this I see in the darkness?"] = "RD_274940ec-6c66-4823-903e-fae16214f54d",
    ["Young one? Is that you I see in the darkness?"] = "RD_c2255b5b-0172-4520-814e-302dcc308f63",
    ["Your beauty will fade, but your kindness will last."] = "RD_13753531-6c12-4762-933a-67c71d7a150a",
    ["Your favorite color is royal blue. Your favorite dessert is cream puffs."] = "RD_3ac91298-cbd6-4cc2-ad44-328681baf850",
    ["Your glass eye, Peters. It broke in the struggle"] = "RD_1d9b8e18-5acf-4105-a840-e314f0e4dcbd",
    ["Your good health means so much."] = "RD_a80f063f-935b-4d1e-89e7-ec1f6ecff06d",
    ["Your investment's about to go... bust."] = "RD_4c8b32d3-4f15-49d4-83ca-9900563996b1",
    ["Your kids could be sick."] = "RD_eafb95d0-c842-4cdd-a5c1-64d98401a874",
    ["Your media elite. You are at fault too."] = "RD_dd790c43-a55d-463d-871f-88335147b055",
    ["Your one stop shop for home improvement!"] = "RD_207759c5-e89e-421e-bc89-61170ee4ba03",
    ["Your reckless actions led directly to Badger's death, Rogue."] = "RD_1b0aa9d0-1c01-4cb9-8471-3d2133c8684b",
    ["Your regional NNR station will have all the details."] = "RD_4c230f0f-0aab-4ecc-bd3b-a7312f765b75",
    ["Your stables are quite impressive Spaffgold, as is your bourbon."] = "RD_bbf983c7-8af4-4ead-8203-5c5ba6cbcab3",
    ["Yours for $1999!"] = "RD_aa542690-9d2e-47a6-8010-54c71049bfc4",
    ["Yours for $3999!"] = "RD_e99b65ba-deb6-4e01-b7a2-06e6f60824ee",
    ["Zachary Bunny - round here we have one rule."] = "RD_7090d052-9908-4102-91d5-3538ac82054e",
    ["Zachary Bunny you may splash water, but on the plants."] = "RD_088847e0-1f6a-45dd-94d4-5b087ca9d05c",
    ["Zachary Bunny!"] = "RD_9792ee4c-b6e4-4000-9e6a-028541d7fd06",
    ["Zachary Bunny! What are you doing?"] = "RD_41488db3-5d88-423d-905e-c088d4249110",
    ["Zachary Bunny, put the dinosaur tail in... here."] = "RD_4e2aea3d-8f85-4062-9f48-c09895c1656c",
    ["Zachary Bunny: it is good to like books about ponies."] = "RD_8ff87b3c-47c1-48d1-be81-4270612ead28",
    ["Zero."] = "RD_194a9df2-f240-41db-b901-ea39f6fa8268",
    ["Zhi-Mei's beautiful and the best."] = "RD_203c21be-a5e8-460d-ab7f-86eb52420de4",
    ["Zhi-Mei's juggling Craft in the air with a Revolving Door Twister - Jerry can't do a thing about it!"] = "RD_7aa1dac5-19aa-4969-9127-016c1af3c633",
    ["Zippee Market: Home of the Slurp Burp."] = "RD_7f89a3c3-018f-4482-bd35-b1380ee1ef33",
    ["[img=music]  And our loooooove will always go on... [img=music]"] = "RD_9c6609ed-a110-4625-b351-227c77ac7dbb",
    ["[img=music]  And you... you know you love me too, ooh. [img=music]"] = "RD_bd4012b5-61cd-4e78-abef-a16c8e3f98f7",
    ["[img=music]  And you... you know you love me too, ooh... [img=music]"] = "RD_8c0be877-f895-486c-a64b-e78b1f3fe566",
    ["[img=music]  Anything that would make you stay. [img=music]"] = "RD_02c8402e-f9d4-4b63-ad42-5e9df56cb934",
    ["[img=music]  Do... [img=music]"] = "RD_6d20ddd4-45dd-4eb1-b4d2-77ac7cf3956e",
    ["[img=music]  Get it Off Your Chest! [img=music]"] = "RD_8824163f-1ae6-4025-aa93-e89cecd333d8",
    ["[img=music]  I can't lie. [img=music]"] = "RD_64c5d49d-09c7-42ce-a538-f964283ec45d",
    ["[img=music]  I need more and more each day! [img=music]"] = "RD_460dd4dc-63d8-4d32-959e-d38853a7a791",
    ["[img=music]  I never wanted to step in your way... [img=music]"] = "RD_f3c521d9-0340-4df7-b668-dd6d44e36781",
    ["[img=music]  If I could say... [img=music]"] = "RD_ad87853e-9d36-48d2-a947-4ad6e7790f86",
    ["[img=music]  If I knew one day I'd meet you... [img=music]"] = "RD_e5e11bda-6b71-41b0-854c-2a7d960ea1df",
    ["[img=music]  Just turn around. It's me you'll see. [img=music]"] = "RD_7d45aae5-2bf5-4842-8ab4-e81102c420a1",
    ["[img=music]  Sweetheart darling, you... [img=music]"] = "RD_db956560-f067-492f-9e6f-d28905fc8019",
    ["[img=music]  With a keen sense of smell... [img=music]"] = "RD_9b8d08a6-cbee-4d95-bf9d-b2837915d849",
    ["[img=music]  With fists and with bullets... [img=music]"] = "RD_8080f388-4e38-407b-9496-ec805e140f05",
    ["[img=music]  You are my morning star, my sun... [img=music]"] = "RD_b2664e4e-b16c-4d59-bdf9-a16de5cd37ef",
    ["[img=music]  You are the moon, the Milky Way... [img=music]"] = "RD_2bc7fc87-f029-4068-b761-6b8c9b1080d5",
    ["[img=music]  You do. [img=music]"] = "RD_a1d4cd82-6614-4d85-a902-e4179ad0e4d4",
    ["[img=music]  You know I would. You know. [img=music]"] = "RD_60d693f2-9aa9-42f9-bd6e-637856128d9b",
    ["[img=music]  You love me too. [img=music]"] = "RD_bdfaaa1b-a4ca-4469-900a-6104a1868963",
    ["[img=music]  You'll know that a true heart can bleed. [img=music]"] = "RD_3270e064-c7f4-4386-961e-8d8087cd8351",
    ["[img=music]  You'll see me cry. [img=music]"] = "RD_a91153da-05fc-49bb-9f99-e74ab14e8c06",
    ["[img=music] \"Give me your soul, and as a reward...\" [img=music]"] = "RD_9cca9556-b986-4f80-8bda-118848a4aba2",
    ["[img=music] \"I can get back if I make God proud.\" [img=music]"] = "RD_ecc05e2c-8a2b-494b-b71f-fdf94bfcffea",
    ["[img=music] \"I'm a fallen angel, got no cloud...\" [img=music]"] = "RD_c072e42d-5f49-4ba8-b8fa-70ccf1dcc62d",
    ["[img=music] \"I've changed, I swear! Life without you, I can't bear!\" [img=music]"] = "RD_91f82f20-e6a3-4a16-bd6d-dc145086c810",
    ["[img=music] \"I've changed, I swear! Need you more than I need air!\" [img=music]"] = "RD_b9ef76f8-f800-4434-b2f1-5d01f34cf7d3",
    ["[img=music] \"We aint got none! Only po-tat-oes!\" [img=music]"] = "RD_c41e2446-e6f9-4fc0-80c7-453099fb943c",
    ["[img=music] \"Will you make an honest deal with me?\" [img=music]"] = "RD_eab63cd8-3f9c-42be-91eb-d0b8753fd825",
