local function getLanguageName()
    if Translator and Translator.getLanguage then
        local language = Translator.getLanguage()
        if language and language.name then
            return tostring(language:name())
        end
    end
    return "CH"
end

local function getActiveLanguageKey()
    local languageName = getLanguageName()
    if languageName == "CN" then
        return "CN"
    end
    return "CH"
end

local function getActiveTextMap()
    return RadioDataFlx.EN_TO_KEY
end

RadioDataFlx._translationCache = RadioDataFlx._translationCache or {}
RadioDataFlx._translationWarned = RadioDataFlx._translationWarned or false

local function decodeJsonString(value)
    if not value then
        return value
    end

    local result = {}
    local index = 1
    while index <= #value do
        local character = value:sub(index, index)
        if character == "\\" then
            local escaped = value:sub(index + 1, index + 1)
            if escaped == '"' or escaped == "\\" or escaped == "/" then
                result[#result + 1] = escaped
                index = index + 2
            elseif escaped == "b" then
                result[#result + 1] = "\b"
                index = index + 2
            elseif escaped == "f" then
                result[#result + 1] = "\f"
                index = index + 2
            elseif escaped == "n" then
                result[#result + 1] = "\n"
                index = index + 2
            elseif escaped == "r" then
                result[#result + 1] = "\r"
                index = index + 2
            elseif escaped == "t" then
                result[#result + 1] = "\t"
                index = index + 2
            elseif escaped == "u" then
                -- 本專案的翻譯 JSON 以 UTF-8 寫入，理論上不會出現非 ASCII \\u。
                -- 若遇到 \\u00xx，至少保留 ASCII 字元；其他碼位交回原 escape，避免錯解。
                local code = tonumber(value:sub(index + 2, index + 5), 16)
                if code and code < 128 then
                    result[#result + 1] = string.char(code)
                else
                    result[#result + 1] = value:sub(index, index + 5)
                end
                index = index + 6
            else
                result[#result + 1] = escaped
                index = index + 2
            end
        else
            result[#result + 1] = character
            index = index + 1
        end
    end

    return table.concat(result)
end

local function loadRadioTranslations(languageKey)
    if RadioDataFlx._translationCache[languageKey] then
        return RadioDataFlx._translationCache[languageKey]
    end

    if not getModFileReader then
        return nil
    end

    local relativePath = "media/lua/shared/Translate/" .. languageKey .. "/RadioData.json"
    local reader = getModFileReader("CatLangFor42", relativePath, false)
    if not reader then
        if not RadioDataFlx._translationWarned then
            RadioDataFlx._translationWarned = true
            print(TAG .. " RadioData_Flx warning: cannot open " .. relativePath)
        end
        return nil
    end

    local translations = {}
    local line = reader:readLine()
    while line do
        local key, rawValue = line:match('^%s*"([^"]+)"%s*:%s*"(.*)"%s*,?%s*$')
        if key and rawValue then
            -- setText 直寫 RadioLine、不經 getText formatted()，故快取須存執行期形（%% → %），
            -- 否則 JSON 含 %% 的譯文會把字面雙百分號顯示在字幕上
            translations[key] = (decodeJsonString(rawValue):gsub("%%%%", "%%"))
        end
        line = reader:readLine()
    end
    reader:close()

    RadioDataFlx._translationCache[languageKey] = translations
    return translations
end

function RadioDataFlx.getLocalizedChannelName(frequency, fallback)
    local entry = RadioDataFlx.CHANNEL_NAMES[tonumber(frequency)]
    if not entry then
        return fallback
    end

    if entry.key and getTextOrNull then
        local translated = getTextOrNull(entry.key)
        if translated then
            return translated
        end
    end

    return entry.fallback or fallback
end

local function javaListSize(list)
    if not list or not list.size then
        return 0
    end
    return list:size()
end

local function isDedicatedServer()
    return isServer and isServer() and (not isClient or not isClient())
end

local function patchLine(line, keyMap, translations)
    if not line or not line.getText or not line.setText then
        return 0
    end

    local text = line:getText()
    local key = text and keyMap[text]
    local translated = key and translations[key]
    if translated and translated ~= text then
        line:setText(translated)
        return 1
    end
    return 0
end

local function randomInt(maxExclusive)
    if ZombRand then
        return ZombRand(maxExclusive)
    end
    return math.random(0, maxExclusive - 1)
end

local function buildAdvertBroadcast(segment, translations)
    if not segment or not segment.lines or not RadioBroadCast or not RadioLine then
        return nil
    end

    local broadcast = RadioBroadCast.new("CatLangFor42-" .. tostring(segment.id), 0, 0)
    for _, lineData in ipairs(segment.lines) do
        local text = translations[lineData.key]
        if text then
            local r = (lineData.r or 255) / 255
            local g = (lineData.g or 255) / 255
            local b = (lineData.b or 255) / 255
            if lineData.codes then
                broadcast:AddRadioLine(RadioLine.new(text, r, g, b, lineData.codes))
            else
                broadcast:AddRadioLine(RadioLine.new(text, r, g, b))
            end
        end
    end

    return broadcast
end

local function patchAdvertSegments(broadcast, translations)
    if not broadcast or not broadcast.getID or not broadcast.setPreSegment or not broadcast.setPostSegment then
        return 0
    end

    local categoryId = RadioDataFlx.BROADCAST_ADVERT_CATEGORIES[tostring(broadcast:getID())]
    if not categoryId then
        return 0
    end

    local segments = RadioDataFlx.ADVERT_CATEGORIES[categoryId]
    if not segments or #segments == 0 then
        return 0
    end

    -- 原版會在 RadioData.loadBroadcast() 以 75% 機率把 advert segment 接到 private
    -- preSegment/postSegment；這些 private 欄位無法安全讀取，但可以用 public setter 重建。
    -- 先清掉原本可能是英文的 segment，再用同等機率掛上中文 segment。
    broadcast:setPreSegment(nil)
    broadcast:setPostSegment(nil)

    if randomInt(101) >= 75 then
        return 0
    end

    local segment = segments[randomInt(#segments) + 1]
    local translatedSegment = buildAdvertBroadcast(segment, translations)
    if not translatedSegment then
        return 0
    end

    if randomInt(101) < 50 then
        broadcast:setPreSegment(translatedSegment)
    else
        broadcast:setPostSegment(translatedSegment)
    end

    return 1
end

local function patchBroadcast(broadcast, keyMap, translations, visitedBroadcasts)
    if not broadcast or not broadcast.getLines then
        return 0
    end

    visitedBroadcasts = visitedBroadcasts or {}
    local broadcastKey = nil
    if broadcast.getID then
        broadcastKey = tostring(broadcast:getID())
    end
    if broadcastKey and visitedBroadcasts[broadcastKey] then
        return 0
    end
    if broadcastKey then
        visitedBroadcasts[broadcastKey] = true
    end

    local count = 0
    local lines = broadcast:getLines()
    for index = 0, javaListSize(lines) - 1 do
        count = count + patchLine(lines:get(index), keyMap, translations)
    end
    count = count + patchAdvertSegments(broadcast, translations)

    return count
end

local function patchScript(channel, script, keyMap, translations, visitedScripts, visitedBroadcasts)
    if not channel or not script or not script.GetGUID then
        return 0
    end

    local guid = script:GetGUID()
    if guid and visitedScripts[guid] then
        return 0
    end
    if guid then
        visitedScripts[guid] = true
    end

    local count = 0
    local broadcasts = script:getBroadcastList()
    for index = 0, javaListSize(broadcasts) - 1 do
        count = count + patchBroadcast(broadcasts:get(index), keyMap, translations, visitedBroadcasts)
    end

    if script.getExitOptions and channel.getRadioScript then
        local exitOptions = script:getExitOptions()
        for index = 0, javaListSize(exitOptions) - 1 do
            local exitOption = exitOptions:get(index)
            if exitOption and exitOption.getScriptname then
                count = count + patchScript(channel, channel:getRadioScript(exitOption:getScriptname()), keyMap, translations, visitedScripts, visitedBroadcasts)
            end
        end
    end

    return count
end

local function patchChannelInternal(channel, keyMap, translations)
    if not channel then
        return 0, 0
    end

    local patchedLines = 0
    local patchedScripts = 0
    local visitedScripts = {}
    local visitedBroadcasts = {}

    if channel.getCurrentScript then
        local count = patchScript(channel, channel:getCurrentScript(), keyMap, translations, visitedScripts, visitedBroadcasts)
        if count > 0 then
            patchedScripts = patchedScripts + 1
            patchedLines = patchedLines + count
        end
    end

    return patchedLines, patchedScripts
end

function RadioDataFlx.patchChannelNames()
    -- Dedicated server 不應把 channel list 改成中文；MP client 端 UI 會依頻率顯示中文名稱。
    -- 這可避免 server preset/channel name 被中文化後，再被原版 UI 以 byte-wise 截斷成亂碼。
    if isDedicatedServer() then
        return
    end

    if not ZomboidRadio or not ZomboidRadio.getInstance then
        return
    end

    local radio = ZomboidRadio.getInstance()
    if not radio or not radio.addChannelName then
        return
    end

    for frequency, entry in pairs(RadioDataFlx.CHANNEL_NAMES) do
        radio:addChannelName(RadioDataFlx.getLocalizedChannelName(frequency, entry.CH), frequency, entry.category, true)
    end
end

function RadioDataFlx.patchRadioScripts(scriptManager)
    if RadioDataFlx._patched then
        RadioDataFlx.patchChannelNames()
        return
    end
    if not scriptManager or not scriptManager.getChannelsList then
        return
    end

    local languageKey = getActiveLanguageKey()
    local keyMap = getActiveTextMap()
    local translations = loadRadioTranslations(languageKey)
    if not keyMap or not translations then
        return
    end

    local patchedLines = 0
    local patchedScripts = 0
    local channels = scriptManager:getChannelsList()

    for index = 0, javaListSize(channels) - 1 do
        local channel = channels:get(index)
        local count, scriptCount = patchChannelInternal(channel, keyMap, translations)
        patchedLines = patchedLines + count
        patchedScripts = patchedScripts + scriptCount
    end

    RadioDataFlx._patched = true
    RadioDataFlx._patchedVersion = RadioDataFlx.PATCH_VERSION
    RadioDataFlx.patchChannelNames()

    if patchedLines > 0 then
        print(string.format("%s RadioData_Flx patched %d live radio/TV lines across %d channels/scripts (%s)", TAG, patchedLines, patchedScripts, languageKey))
    end
end

function RadioDataFlx.onLoadRadioScripts(scriptManager, _isNewGame)
    RadioDataFlx.patchRadioScripts(scriptManager)
end

function RadioDataFlx.patchRadioScriptsFromInstance()
    if not ZomboidRadio or not ZomboidRadio.getInstance then
        return
    end

    local radio = ZomboidRadio.getInstance()
    if radio and radio.getScriptManager then
        RadioDataFlx.patchRadioScripts(radio:getScriptManager())
    else
        RadioDataFlx.patchChannelNames()
    end
end

function RadioDataFlx.onRefreshChannelNames()
    -- MP client 會在連線後收到 server channel list，可能覆寫本地名稱；前幾分鐘低頻重套即可。
    RadioDataFlx.patchChannelNames()
    RadioDataFlx._channelPatchTicks = RadioDataFlx._channelPatchTicks + 1
    if RadioDataFlx._channelPatchTicks >= 5 and Events.EveryOneMinute then
        Events.EveryOneMinute.Remove(RadioDataFlx.onRefreshChannelNames)
    end
end

if Events.OnLoadRadioScripts then
    Events.OnLoadRadioScripts.Add(RadioDataFlx.onLoadRadioScripts)
end
if Events.OnGameStart then
    Events.OnGameStart.Add(RadioDataFlx.patchRadioScriptsFromInstance)
end
if Events.OnConnected then
    Events.OnConnected.Add(RadioDataFlx.onRefreshChannelNames)
end
if Events.EveryOneMinute then
    Events.EveryOneMinute.Add(RadioDataFlx.onRefreshChannelNames)
end
